// Build Run Context — MV Overstay Fines (v1)
//
// WHY THIS NODE EXISTS. It emits the SAME payload the portal used to post to the
// webhook, and hands it to the UNMODIFIED `Validate Inputs`. Every guard in that
// node still runs — the shared-secret compare, the callback allowlist, the window
// parser, the previous-cases handling. Nothing downstream can tell how the run
// started.
//
// 2026-08-30: it is now fed by BOTH the monthly schedule and the manual trigger.
// The webhook, the two respond nodes and the three callback nodes are disabled
// under the no-webhook ruling; n8n forwards through a disabled node, so every
// downstream branch still receives data while nothing leaves the flow. The
// production export strips them entirely.
//
// THE TOKEN. The Skeleton Contract's Secrets rule is absolute: no token, key or
// password in any code node or header literal. ERP auth is supplied INSIDE the HTTP
// Request node as an n8n CREDENTIAL. Both hold at once, because the bearer value
// below is a SENTINEL, not a secret: it exists only to satisfy `Validate Inputs`,
// which refuses to run without a token, and its shape check. The real token never
// appears in this workflow at all — it lives in the ERP credential and n8n injects
// it at request time, and none of the ERP nodes here read `params.erp_auth.bearer`.
//
// NOTE FOR DEPLOYMENT: that credential currently holds a dated STAGING token. A
// staging token must not travel to production inside an export — the deploying team
// creates the credential with a production token.
const MANUAL_TOKEN_SENTINEL = 'Bearer credential.supplied.by.the.n8n.http.request.node';

// The shared secret `Validate Inputs` requires. It is NOT introduced here — it is
// already a cleartext constant inside that node, which documents plainly that it is
// "not a real secret against an insider". Repeating it on this path adds no exposure,
// and with the webhook disabled it guards nothing that is reachable from outside.
const WEBHOOK_SECRET = 'LAWP';

// `Validate Inputs` REQUIRES a callback_url and validates it against an origin
// allowlist plus a strict path shape, and that guard is not ours to weaken. This
// value is a deliberately inert placeholder: a valid shape, an all-zero token, and
// — since 2026-08-30 — no enabled node downstream that could reach it even if it
// were real. The open gap about which callback path belongs to THIS check is now
// moot: the portal route is retired, not merely undeclared.
const INERT_CALLBACK =
  'https://nnbyjbdbigcpoqtsczlz.supabase.co/functions/v1/ta-callback/' + '0'.repeat(64);

// THE WINDOW FOLLOWS THE CALENDAR (2026-08-30). It used to be two hand-edited
// constants pinned to June 2026 — "the only thing a manual re-run changes" — which a
// monthly schedule cannot use: an unattended run would have re-audited June forever.
// A run on the 15th audits the PREVIOUS FULL CALENDAR MONTH; the two-week lag lets
// payments settle. Set the OVERRIDE constants to pin a window for a one-off re-run.
const OVERRIDE_FROM = null;   // e.g. '2026-06-01'
const OVERRIDE_TO   = null;   // e.g. '2026-06-30'
function previousFullMonth() {
  const n = new Date();
  const first = new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth() - 1, 1));
  const y = first.getUTCFullYear();
  const m = first.getUTCMonth() + 1;
  const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const p = function (x) { return String(x).padStart(2, '0'); };
  return { from: y + '-' + p(m) + '-01', to: y + '-' + p(m) + '-' + p(last) };
}
const _win = previousFullMonth();
const WINDOW_FROM = OVERRIDE_FROM || _win.from;
const WINDOW_TO   = OVERRIDE_TO   || _win.to;
const IS_PINNED   = !!(OVERRIDE_FROM || OVERRIDE_TO);

const runId = (IS_PINNED ? 'manual-' : 'sched-') + $execution.id + '-' + WINDOW_FROM.slice(0, 7);

return [{
  json: {
    headers: { 'x-sr-webhook-secret': WEBHOOK_SECRET },
    query: {},
    params: {},
    body: {
      check_id: 'mv-overstay-fines',
      run_id: runId,
      callback_url: INERT_CALLBACK,
      audit_window: { kind: 'date_range', from: WINDOW_FROM, to: WINDOW_TO },
      params: {
        erp_auth: { bearer: MANUAL_TOKEN_SENTINEL },
        previous_cases: [],
        check_name: 'MV Overstay Fines',
        // Records HOW the window was chosen, so a Runs row says whether a human picked it.
        trigger_source: IS_PINNED ? 'manual' : 'scheduled',
        // ERP CALL BUDGET - A RECORDED HUMAN DECISION, which is exactly what the gate asks
        // for. Execution 100774 projected 2,109 calls for this window and ERP Budget Gate
        // refused against its DEFAULT_BUDGET of 2,000: "Refusing to start the per-entity
        // phase." That refusal was CORRECT - the gate exists so a run cannot widen silently,
        // and its own comment says "params.erp_call_budget is that record".
        //
        // Raised to 2,500 on the owner's instruction, 2026-08-24. That clears June's 2,109
        // with ~18% headroom rather than sitting on the line, where a handful of extra
        // transactions would refuse again.
        //
        // IT IS NOT A LICENCE FOR ANY WINDOW. The gate re-projects from the actual cohort
        // every run; a wider window can still exceed 2,500 and refuse, and that refusal will
        // be correct too. Raise it again only with the same deliberateness - the number is a
        // decision about ERP load, not a formality to clear.
        //
        // NOTE 2026-08-30: a scheduled run is now always ONE month, so the projection should
        // be stable month to month rather than varying with a hand-picked window.
        erp_call_budget: 2500,
        // The declared delivery targets for this run. Additive, and none of them changes a
        // case. CORRECTED 2026-08-30: workbook was false, but this flow has three Google
        // Sheets nodes and under the ruling the workbook IS the delivery mechanism, so the
        // declaration now matches the wiring. Portal is off and now permanently so - the
        // callback nodes are disabled and are stripped from the production export, so this
        // is no longer a delivery CHOICE with the nodes "present and untouched".
        delivery: { portal: false, data_tables: true, workbook: true, email: false, runs_log: true }
      }
    }
  }
}];

// Validate Inputs - Travel Assist Payments Audit (v4)
//
// SOURCE OF TRUTH: E:/Claude Code/n8n/travel_assist/validate_inputs.js
//
// CHANGES vs v3 (2026-08-06) - SECURITY HARDENING. Three holes, all reachable
// from the open internet because the Webhook node has no authentication of its
// own (`options: {}`), and this node is the only thing standing between a POST
// and eleven authenticated ERP reads:
//
//   1. EXFILTRATION VIA callback_url (the serious one). `callback_url` was
//      accepted verbatim and later POSTed to with the ENTIRE audit - client
//      names, contract ids, maid names, every payment figure - and again with
//      the AI verdicts. Anyone who could reach the webhook could name their own
//      host and have this workflow courier the audit to it. It is now checked
//      against an ORIGIN ALLOWLIST plus the exact `/ta-callback/<64-hex>` path
//      shape. Nothing else can receive this data, whatever the caller asks for.
//      (`Merge Agent Verdicts` derives the agent-review URL from this same
//      value, so allowlisting here covers both callbacks.)
//
//   2. THE SHARED SECRET WAS SENT BUT NEVER CHECKED. `ta-trigger-run` has been
//      sending `X-SR-Webhook-Secret` on every call - confirmed live in the
//      request headers of execution 77442 - and nothing in this workflow ever
//      looked at it. It is now required. That turns "anyone who knows the URL"
//      into "anyone who knows the URL AND the secret".
//      NOT A REAL SECRET AGAINST AN INSIDER: it travels in plaintext, appears
//      in every execution's data, and is compared against a constant below, so
//      anyone with read access to this n8n project can see it. It exists to
//      keep strangers out, not colleagues. Rotating it to a random value in an
//      `httpHeaderAuth` credential on the Webhook node is the open item - that
//      needs a UI click (the n8n API cannot attach credentials) and a matching
//      change to the portal's SR_WEBHOOK_SECRET secret, in that order.
//
//   3. HEADER INJECTION VIA THE BEARER TOKEN. `params.erp_auth.bearer` is
//      interpolated straight into the `authorization` header of eleven HTTP
//      nodes. A value containing CR/LF could smuggle extra headers into those
//      requests. It is now shape-checked (`Bearer <JWT>`, no control chars).
//
// CHANGES vs v2 (2026-08-06):
//   ERP auth is supplied by the CALLER again. ta-trigger-run now reads the
//   token belonging to the triggering user from the portal `erp_credentials`
//   table and sends it as params.erp_auth.bearer (it already carries the
//   'Bearer ' prefix), and the 11 ERP nodes read it from there instead of the
//   shared "ERP Hassan Prod" credential.
//
//   The token is validated HERE because every ERP node depends on it: without
//   this check a missing token fails eleven nodes one at a time on an
//   unresolvable expression, which is both noisy and hard to read. Tokens in
//   erp_credentials expire after 24h, so a missing or stale one is a NORMAL,
//   expected rejection - the caller re-saves the token and triggers again.
//
// CHANGES vs v1 (2026-08-05):
//   `auth` (the old auth.erp.token shape) is no longer required. An `auth`
//   object from an older caller is accepted and ignored, so a stale Security
//   Room deploy degrades gracefully instead of hard-failing.

const incoming = $input.first().json || {};
const payload = incoming.body || incoming || {};
const headers = incoming.headers || {};

// ---------------------------------------------------------------- security ---
// Header names arrive lowercased from n8n's webhook node; read defensively
// anyway so a proxy that preserves case cannot bypass the check.
function header(name) {
  const want = name.toLowerCase();
  for (const k of Object.keys(headers)) {
    if (k.toLowerCase() === want) return String(headers[k] || '');
  }
  return '';
}

// Length-independent compare. Not a defence against a real timing attack over
// the internet (jitter swamps it), but it costs nothing and stops the trivial
// prefix-probing case.
function safeEqual(a, b) {
  const A = String(a), B = String(b);
  let diff = A.length ^ B.length;
  for (let i = 0; i < Math.max(A.length, B.length); i++) {
    diff |= (A.charCodeAt(i) || 0) ^ (B.charCodeAt(i) || 0);
  }
  return diff === 0;
}

// The value the portal has been sending all along (see header comment #2).
const EXPECTED_WEBHOOK_SECRET = 'LAWP';

// A single literal has no rotation ordering that avoids an outage: change the portal
// first and every call is rejected here; change here first and every call is rejected
// by the portal's old value. So the check takes a SET, and both slots are accepted at
// once. Rotation becomes: (1) add the new secret to this array, (2) switch the portal,
// (3) confirm from the secret_slot_matched log line below that live traffic is arriving
// on the new slot, (4) remove the old entry. No window in which both sides disagree.
//
// Slot names are logged, VALUES ARE NEVER LOGGED. 'live' is the value the portal has
// been sending all along.
const ACCEPTED_WEBHOOK_SECRETS = [
  { slot: 'live',     value: EXPECTED_WEBHOOK_SECRET },
  { slot: 'rotating', value: 'OAhz0nSVf3rtx7oSquAK-8xJrlUYdfKERWV217qpk40' }
];

// Only these origins may receive the audit results. Both are real: the
// Cloudflare Worker proxy the portal normally uses, and the direct Supabase
// functions host it falls back to when CALLBACK_BASE_URL is unset.
const CALLBACK_ORIGIN_ALLOWLIST = [
  'https://security-room-n8n-callback-proxy.hassan-ahmed-e4c.workers.dev',
  'https://nnbyjbdbigcpoqtsczlz.supabase.co'
];
// `Merge Agent Verdicts` requires '/ta-callback/' in this URL to derive the
// agent-review endpoint, and the token is 32 random bytes hex-encoded.
const CALLBACK_PATH_RE = /^(?:\/functions\/v1)?\/ta-callback\/[0-9a-f]{64}$/;

// Split an https URL into [origin, path] WITHOUT the global `URL` constructor.
//
// This is not stylistic. n8n's Code sandbox does not expose `URL`, so the first
// version of this guard - which called `new URL(callback_url)` inside a
// try/catch - threw on EVERY request and rejected every caller, including the
// portal. It looked like a working allowlist in offline tests and in the three
// live attack probes; it was actually a total outage of the audit, and only a
// probe with a VALID callback_url exposed it (the guard fired for the wrong
// reason). Hence: parse with a regex, and prove the parser survives `URL` being
// undefined - security.test.mjs runs this file with the global shadowed away.
//
// The pattern is deliberately strict rather than lenient:
//   [^/?#@]+  host cannot contain '@', so `https://allowed.host@evil.com/...`
//             (userinfo trick) cannot borrow an allowlisted origin
//   no '?'/'#' in the path group, so nothing can be appended after the token
//   https only - a plaintext downgrade of an allowed host is not an allowed host
function splitHttpsUrl(raw) {
  const s = String(raw || '');
  // Control characters, whitespace and backslashes have no business in a URL we
  // are about to POST client payment data to.
  if (/[^\x21-\x7e]/.test(s)) return null;   // printable ASCII only
  if (s.indexOf('\\') !== -1) return null;
  const m = /^(https:\/\/[^/?#@]+)(\/[^?#]*)$/.exec(s);
  if (!m) return null;
  if (m[2].indexOf('..') !== -1) return null;   // no traversal off the callback route
  return { origin: m[1], path: m[2] };
}

function reject(message, extra) {
  return [{ json: Object.assign({
    _error: true,
    message: message,
    check_id:     payload.check_id     || '',
    run_id:       payload.run_id       || '',
    // Deliberately NOT echoing the caller's callback_url on a rejection: on the
    // paths that reject for security reasons it is exactly the value we refuse
    // to trust, and Build Error Callback would POST to it.
    callback_url: ''
  }, extra || {})}];
}

const providedSecret = header('x-sr-webhook-secret');
// EVERY slot is compared, and the loop does not break early: bailing out on the first
// match would make the number of comparisons depend on which slot matched, which is the
// timing leak safeEqual exists to avoid. matchedSlot is assigned, not returned.
let matchedSlot = '';
for (let i = 0; i < ACCEPTED_WEBHOOK_SECRETS.length; i++) {
  const cand = ACCEPTED_WEBHOOK_SECRETS[i];
  if (providedSecret && safeEqual(providedSecret, cand.value)) matchedSlot = cand.slot;
}
if (!matchedSlot) {
  // Terse on purpose - do not tell an unauthenticated caller which part failed.
  //
  // `_silent` suppresses the failure EMAIL for this branch only, and that is a
  // deliberate trade, not laziness: this is the one rejection an anonymous
  // caller can trigger at will, so alerting on it hands anyone who finds the
  // URL a mail-bomb aimed at Abdullah's inbox. The rejection is still recorded
  // in the n8n execution list, which is where you go to see whether someone is
  // knocking. Every other rejection below still emails, because reaching those
  // requires knowing the secret - that is a colleague or a leak, both worth
  // waking up for.
  return reject('unauthorized', { _silent: true });
}

const required = ['check_id', 'run_id', 'callback_url', 'audit_window'];
const missing = required.filter(k =>
  payload[k] === undefined || payload[k] === null || payload[k] === ''
);
if (missing.length) {
  return [{ json: {
    _error: true,
    message: 'Missing required field(s): ' + missing.join(', '),
    check_id:     payload.check_id     || '',
    run_id:       payload.run_id       || '',
    callback_url: payload.callback_url || ''
  }}];
}

// ----- callback_url: WHERE the audit is allowed to be sent -----
// Checked before anything else touches ERP, because this single field decides
// who receives every figure this run produces.
const cbRaw = String(payload.callback_url || '');
const cbUrl = splitHttpsUrl(cbRaw);
if (!cbUrl ||
    CALLBACK_ORIGIN_ALLOWLIST.indexOf(cbUrl.origin) === -1 ||
    !CALLBACK_PATH_RE.test(cbUrl.path)) {
  return reject('callback_url is not an approved Security Room callback endpoint. ' +
    'This audit will only post results to a known host on the exact ' +
    '/ta-callback/<token> path - refusing to send client payment data anywhere else.');
}

const w = payload.audit_window;
if (!w || typeof w !== 'object' || !w.kind) {
  return [{ json: { _error: true, message: 'audit_window missing or malformed',
    check_id: payload.check_id, run_id: payload.run_id, callback_url: payload.callback_url }}];
}

// ----- ERP token (caller-supplied) -----
const erpAuth = (payload.params && payload.params.erp_auth) || {};
const bearer = typeof erpAuth.bearer === 'string' ? erpAuth.bearer.trim() : '';
if (!bearer) {
  return [{ json: { _error: true,
    message: 'params.erp_auth.bearer is required - every ERP call in this audit ' +
             'authenticates with the caller-supplied token. In the Security Room it comes ' +
             'from the saved ERP credentials of the triggering user; if it is missing or has ' +
             'expired (they last 24h), re-save the token and trigger the run again.',
    check_id: payload.check_id, run_id: payload.run_id, callback_url: payload.callback_url }}];
}
// Shape check, not a validity check: this string is interpolated into the
// `authorization` header of eleven HTTP nodes, so a CR/LF in it could append
// attacker-chosen headers to authenticated ERP requests. ERP itself decides
// whether the token is good.
if (!/^Bearer [A-Za-z0-9._~+/=-]+$/.test(bearer)) {
  return reject('params.erp_auth.bearer is malformed - expected "Bearer <token>" ' +
    'with no whitespace or control characters. Re-save the ERP token in the portal.');
}

function pad(n) { return String(n).padStart(2, '0'); }
let range_start, range_end, audit_month;

if (w.kind === 'month') {
  const year = parseInt(w.year, 10), month = parseInt(w.month, 10);
  if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) {
    return [{ json: { _error: true, message: 'audit_window.month invalid: ' + JSON.stringify(w),
      check_id: payload.check_id, run_id: payload.run_id, callback_url: payload.callback_url }}];
  }
  range_start = year + '-' + pad(month) + '-01';
  range_end   = year + '-' + pad(month) + '-' + pad(new Date(year, month, 0).getDate());
  audit_month = year + '-' + pad(month);
} else if (w.kind === 'date_range') {
  const re = /^\d{4}-\d{2}-\d{2}$/;
  if (!re.test(w.from || '') || !re.test(w.to || '') || w.to < w.from) {
    return [{ json: { _error: true, message: 'audit_window date_range invalid',
      check_id: payload.check_id, run_id: payload.run_id, callback_url: payload.callback_url }}];
  }
  range_start = w.from;
  range_end   = w.to;
  audit_month = w.from.slice(0, 7);
} else {
  return [{ json: { _error: true, message: 'audit_window.kind unsupported: ' + w.kind,
    check_id: payload.check_id, run_id: payload.run_id, callback_url: payload.callback_url }}];
}

const previous_cases = Array.isArray(payload.params && payload.params.previous_cases)
  ? payload.params.previous_cases
  : [];

// The SLOT, never the value. This one line is what makes the rotation verifiable: after
// the portal is switched, a run logging secret_slot_matched 'rotating' proves live
// traffic is on the new secret, and only then is the old slot safe to delete.
console.log(JSON.stringify({ stage: 'validate_inputs', secret_slot_matched: matchedSlot,
  accepted_slots: ACCEPTED_WEBHOOK_SECRETS.map(function (c) { return c.slot; }),
  note: 'slot names only - the secret value is never logged, and it must never be added ' +
        'here even temporarily: every log line lands in the stored execution record.' }));

return [{ json: {
  _error: false,
  check_id:     payload.check_id,
  run_id:       payload.run_id,
  callback_url: payload.callback_url,
  audit_window: w,
  audit_month, range_start, range_end,
  range_start_dt: range_start + ' 00:00:00',
  range_end_dt:   range_end + ' 23:59:00',
  auth_mode:    'caller_payload:params.erp_auth.bearer',
  webhook_secret_slot: matchedSlot,
  params:       payload.params || {},
  previous_cases
}}];

// Build Error Callback (v4)
//
// v1 silently SWALLOWED real ERP failures. Proven live in execution 76767: an ERP
// 498 "Access Token is missing or malformed" produced
//   {result:'ok', _suppressed:true, _reason:'no upstream error signal'}
// twice, and the run reported success with no callback at all. Two causes:
//   1. n8n's HTTP error item has NO `error.message`. The text lives in
//      `error.error` as a JSON *string*, alongside error.statusCode,
//      error.response.status and isAxiosError. v1 only read error.message.
//   2. `_error` is FALSE on those items - Validate Inputs sets `_error:false` and
//      the field flows downstream - so `first._error === true` could never fire,
//      and v1 read that as evidence there was no error.
//
// Classification is driven by STATUS CODE first and substring matching last.
// v1's `msg.includes('5') && msg.includes('0')` matched any message containing a
// 5 and a 0, so seven-digit contract ids tripped it and `timeout` was unreachable.
//
// DEDUPE (v3): the bulk pulls run in PARALLEL, so several branches can fail at the
// same instant and this node gets triggered once per failing branch. Execution
// 76796 sent TWO error callbacks for one run - and would now send two alert emails.
// Only the first run emits; later runs return nothing, so Error Gate stays empty
// and neither the callback nor the email fires twice.
//
// CONTEXT RECOVERY (v4): execution 77172 emitted check_id/run_id/callback_url all
// EMPTY, so `Callback - Error` failed with "URL parameter cannot be empty" and the
// Security Room was never told the run had died - it would sit on "running" for
// ever. Cause: context came only from `$('Validate Inputs').first()`, which THROWS
// when n8n cannot trace paired-item lineage back from an arbitrary failed node.
// The empty catch swallowed that, and every remaining fallback read the HTTP error
// item, which of course carries no run identifiers. v4 therefore tries several
// INDEPENDENT accessors and accepts only a candidate that actually carries a
// callback_url - losing the callback URL is the one failure that makes this whole
// node pointless.
if ($runIndex > 0) {
  console.log(JSON.stringify({ stage: 'build_error_callback',
    suppressed_duplicate: true, run_index: $runIndex }));
  return [];
}

function tryGet(fn) {
  try {
    const v = fn();
    return (v && typeof v === 'object') ? v : null;
  } catch (e) { return null; }
}
function hasUrl(o) { return !!(o && typeof o.callback_url === 'string' && o.callback_url.trim()); }

const candidates = [
  tryGet(function () { return $('Validate Inputs').first().json; }),
  tryGet(function () { return $('Validate Inputs').all()[0].json; }),
  tryGet(function () { const j = $('Webhook').first().json; return j.body || j; }),
  tryGet(function () { const j = $('Webhook').all()[0].json; return j.body || j; })
];
let ctx = null;
for (let i = 0; i < candidates.length; i++) {
  if (hasUrl(candidates[i])) { ctx = candidates[i]; break; }
}
if (!ctx) { for (let i = 0; i < candidates.length; i++) { if (candidates[i]) { ctx = candidates[i]; break; } } }
ctx = ctx || {};

// READ THE FAILURE FROM Capture Failure, NOT FROM $input. This node sits AFTER
// Release Lease (error) on the rail, and that is an Execute Sub-workflow node - it does not pass
// its input through, it REPLACES the item with whatever the lease workflow returned. So $input
// here holds the lease's answer, not the error, and every callback and every message this node
// produced would have said "unknown". Added 2026-08-23.
//
// This flow was the last one in the repo still carrying the bug, and it was the HARDEST to see:
// the other twelve lost the error in `Fail Loudly`, directly downstream of the lease call, and a
// checker looking at the throwing node's own predecessors found them. Here the loss happens one
// hop earlier, in a node that does not throw at all, so `Fail Loudly` looked innocent and this
// flow was twice reported as the ONE correct rail in the estate. The rule now walks the rail
// transitively and asks which node DERIVES the error, not which one throws.
const first = ($('Capture Failure').first().json || {})._failure || {};
const err = (first.error && typeof first.error === 'object') ? first.error : {};

function firstString() {
  for (let i = 0; i < arguments.length; i++) {
    const v = arguments[i];
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
}
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }

const raw = firstString(err.message, err.error, first.message,
                        typeof first.error === 'string' ? first.error : '');
let parsed = null;
if (raw && raw.charAt(0) === '{') {
  try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
}
const erpMessage = parsed ? firstString(parsed.message, parsed.error) : '';
const upstreamMsg = firstString(erpMessage, raw,
                                first._error === true ? 'input validation failed' : '');
const status = num(parsed && parsed.status)
            || num(err.statusCode)
            || num(err.response && err.response.status)
            || num(first.status)
            || null;

const hasRealError = !!(
  upstreamMsg || status ||
  first._error === true ||
  err.name || err.stack || err.isAxiosError === true ||
  Object.keys(err).length > 0
);
if (!hasRealError) {
  return [{ json: { result: 'ok', _suppressed: true, _reason: 'no upstream error signal' } }];
}

const msg = String(upstreamMsg).toLowerCase();
let code = 'internal';
if (first._error === true && !status) {
  code = 'validation';
} else if (status === 401 || status === 403 || status === 498 ||
           msg.indexOf('access token') !== -1 || msg.indexOf('logout') !== -1 ||
           msg.indexOf('unauthorized') !== -1 || msg.indexOf('unauthorised') !== -1) {
  code = 'erp_auth_expired';
} else if (msg.indexOf('timeout') !== -1 || msg.indexOf('etimedout') !== -1 ||
           msg.indexOf('econnaborted') !== -1 || msg.indexOf('econnreset') !== -1) {
  code = 'timeout';
} else if (status && status >= 500) {
  code = 'erp_unavailable';
} else if (status && status >= 400) {
  code = 'erp_rejected';
}

const detail = status ? ('HTTP ' + status + ' - ' + (upstreamMsg || 'no message'))
                      : (upstreamMsg || 'Unknown error');

const check_id     = firstString(ctx.check_id,     first.check_id,     first.body && first.body.check_id);
const run_id       = firstString(ctx.run_id,       first.run_id,       first.body && first.body.run_id);
const callback_url = firstString(ctx.callback_url, first.callback_url, first.body && first.body.callback_url);

// Loud, because a silent version of this is what execution 77172 did.
if (!callback_url) {
  console.log(JSON.stringify({ stage: 'build_error_callback',
    context_recovery_failed: true,
    note: 'no callback_url could be recovered - the portal cannot be notified of this failure' }));
}

return [{ json: {
  check_id: check_id,
  run_id: run_id,
  callback_url: callback_url,
  result: 'error',
  error: {
    code: code,
    message: detail,
    status: status,
    retryable: code === 'erp_unavailable' || code === 'timeout'
  },
  notes: 'Audit did not complete.',
  completed_at: new Date().toISOString()
}}];

parameters.jsonBody:
={{ JSON.stringify([
  { property: "expense.id", operation: "=", value: 1677 },
  { property: "date", operation: "between", value: $('Validate Inputs').first().json.range_start, secondValue: $('Validate Inputs').first().json.range_end }
]) }}

parameters.jsCode:
// Format Failure Email - normalises TWO very different failure shapes into one
// readable email.
//
// Shape A - handled: the error rail's payload from Build Error Callback,
//   { result:'error', error:{ code, message, status, retryable }, run_id, ... }
//
// Shape B - crash: n8n's Error Trigger payload,
//   { execution:{ id, url, error:{ message, stack }, lastNodeExecuted }, workflow:{ id, name } }
//
// Both matter and they catch different things. The rail only sees an ERP call that
// routed to its error output. A THROW - Verify Bulk Pulls in execution 76796 -
// aborts the run and never touches the rail. Without the crash trigger, the loudest
// failures were the silent ones.

const j = $input.first().json || {};
const isCrash = !!(j.execution || j.workflow);

let runId, nodeName, code, message, status, retryable, execId, execUrl, wfName;

if (isCrash) {
  const ex = j.execution || {};
  const wf = j.workflow || {};
  execId   = ex.id || '';
  execUrl  = ex.url || '';
  wfName   = wf.name || 'MV Overstay Fines Audit';
  nodeName = ex.lastNodeExecuted || '(unknown node)';
  message  = (ex.error && (ex.error.message || ex.error.description)) || 'no message';
  code     = 'workflow_crash';
  status   = null;
  retryable = false;
  try { runId = $('Validate Inputs').first().json.run_id; } catch (e) { runId = '(unknown)'; }
} else {
  const e = j.error || {};
  runId    = j.run_id || '(unknown)';
  nodeName = '(handled - see error rail)';
  code     = e.code || 'internal';
  message  = e.message || 'no message';
  status   = e.status != null ? e.status : null;
  retryable = e.retryable === true;
  wfName   = 'MV Overstay Fines Audit';
  execId = ''; execUrl = '';
}

// What to check first, by failure type. A 498 is overwhelmingly the likely one
// right now: eleven nodes still need their credential attached by hand.
let advice;
if (code === 'erp_auth_expired' || status === 498 || status === 401 || status === 403) {
  advice = 'ERP rejected the credential. Check that every ERP node in the workflow has the ' +
           '"ERP Hassan Prod" credential selected, and that the credential itself is still valid. ' +
           'A 498 means the token is missing or malformed - retrying will not help.';
} else if (code === 'timeout') {
  advice = 'ERP did not respond in time. The nodes allow 90s. If this recurs, ERP is slow ' +
           'under load - consider capping concurrency (batchSize) rather than raising the timeout.';
} else if (code === 'erp_unavailable') {
  advice = 'ERP returned a 5xx. Usually transient - this one IS retryable.';
} else if (code === 'workflow_crash') {
  advice = 'A node threw rather than routing to the error rail. If it was "Verify Bulk Pulls" ' +
           'or "Split Transactions", that is a GUARD firing on purpose: an ERP pull returned no ' +
           'usable data and the run was stopped so it could not report a successful audit of ' +
           'zero cases. Read the message above - it names which pull failed.';
} else {
  advice = 'Open the execution in n8n and read the failing node\'s input and output.';
}

const subject = '[MV Overstay Fines Audit] FAILED - ' + code +
                (status ? ' (HTTP ' + status + ')' : '') +
                ' - run ' + String(runId).slice(0, 8);

function esc(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const rows = [
  ['What broke', isCrash ? ('a node threw: ' + nodeName) : 'an ERP call failed (handled)'],
  ['Error code', code],
  ['ERP status', status != null ? String(status) : '-'],
  ['Message', message],
  ['Retryable', retryable ? 'yes' : 'no'],
  ['Run id', runId],
  ['Execution', execId ? (execUrl ? ('<a href="' + esc(execUrl) + '">' + esc(execId) + '</a>') : esc(execId)) : '-']
];

const html =
  '<div style="font-family:Calibri,Arial,sans-serif;max-width:640px;">' +
  '<div style="background:#DC2626;color:#fff;padding:12px 16px;font-size:16px;font-weight:bold;">' +
  'MV Overstay Fines Audit - run failed</div>' +
  '<div style="padding:12px 16px;">' +
  '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
  rows.map(function (r) {
    return '<tr>' +
      '<td style="padding:5px 8px;border-bottom:1px solid #E2E8F0;color:#64748B;width:120px;">' + esc(r[0]) + '</td>' +
      '<td style="padding:5px 8px;border-bottom:1px solid #E2E8F0;">' + (r[0] === 'Execution' ? r[1] : esc(r[1])) + '</td>' +
      '</tr>';
  }).join('') +
  '</table>' +
  '<div style="background:#FEF3C7;border-left:4px solid #B45309;padding:10px 12px;margin-top:14px;font-size:12.5px;">' +
  '<strong>What to check first.</strong><br>' + esc(advice) + '</div>' +
  '<div style="margin-top:12px;font-size:11px;color:#94A3B8;">No audit result was written for this run. ' +
  'Security Room will show it as failed rather than passing with an empty cohort.</div>' +
  '</div></div>';

return [{ json: { subject: subject, html: html, failure_code: code,
                  run_id: runId, execution_id: execId } }];

// Verify Cohort Pull — MV Overstay Fines (v1)
//
// Adapted from the golden's `Verify Bulk Pulls`: same job, one pull instead of
// three. Sits immediately after the cohort request so nothing downstream can
// score a cohort built on a failed or partial ERP fetch.
//
// Three separate obligations, and they are NOT the same check:
//   1. PAGINATION — every page collected, content.length summed == totalElements.
//   2. POPULATION — the count measured against the magnitude the check declares.
//      The Skeleton Contract is explicit that (1) does not prove (2): totalElements
//      comes from the same query, so it can only confirm the filter agrees with
//      itself, and it will happily certify a flawless walk of the wrong set.
//   3. EMPTY IS NOT CLEAN — `change_of_status_transaction` Default Value: an empty
//      result ABORTS the run. A month with zero change-of-status transactions is a
//      broken query, not a clean month.
//
// ERP-COMPLIANCE: no-breaker-because this node reads a PAGINATED SWEEP, not a
// per-entity fan-out, and the walk already stops itself sooner and harder than a
// breaker reading the finished batch could. Taking the three §5 thresholds in turn:
// consecutive_failures and degraded_rate cannot be evaluated on a batch this small
// (January, the largest month measured, is 811 rows = 5 pages at size=200, and the
// rate rule needs 20 responses before it will speak at all); latency cannot fire
// because there is exactly one sweep per run, so there is no earlier batch of the
// same key to baseline against, and no node in this flow stamps erp_t0. What stops
// the run instead is stronger than any of them: the assertions below THROW on an
// ERP error body, on a missing content array, on a walk that does not reconcile to
// totalElements, on an empty cohort and on a cohort under the declared floor of
// 100. A single failed page therefore ends the run here, before the per-entity
// phase that a breaker exists to protect has made one call. The per-entity fan-outs
// each carry a real breaker of their own: Judge Detail Batch, Judge Fines Batch,
// Judge Payments Batch, Judge Complaints Batch, Judge Threads Batch.
const EXPENSE_ID = 1677;
const PAGE_SIZE = 200;

// Expected cohort magnitude, from the population row's Example Values, MEASURED
// live 2026-08-12: August 2026 totalElements 151 (8 pages at size=20), January
// 811, March 664. The floor is a tripwire on the smallest month observed.
//
// THE FLOOR IS NEVER LOWERED TO MATCH AN OBSERVED RUN. A cohort under it is a
// cohort bug until proven otherwise, with evidence from a source other than the
// query that produced it. Recalibrating this number to whatever a run returned
// does not fix the check; it permanently and silently blesses the defect the
// tripwire exists to catch.
const COHORT_FLOOR = 100;

const pages = $input.all().map(function (i) { return i.json; });

if (pages.length === 0) {
  throw new Error('Get Change of Status Transactions produced no response at all — ' +
    'refusing to report an empty audit as success.');
}

let collected = 0;
let totalElements = null;
const rows = [];

for (const p of pages) {
  const looksLikeError = p && !Array.isArray(p.content) && (p.status || p.message || p.error || p.path);
  if (looksLikeError) {
    throw new Error('Cohort request returned an ERP error body instead of transactions: status=' +
      (p.status || '?') + ' message=' + (p.message || p.error || '?') + ' path=' + (p.path || '?') +
      ' — refusing to score an empty cohort. A 401 here is a wrong pagecode or an expired ' +
      'token, NEVER "no data": pagecode ManageTransactions is load-bearing and a wrong one ' +
      '401s silently (measured 2026-08-12 on this check\'s own endpoints).');
  }
  if (!p || !Array.isArray(p.content)) {
    throw new Error('Cohort response has no `content` array — shape changed? keys=' +
      Object.keys(p || {}).join(','));
  }
  collected += p.content.length;
  if (totalElements === null && p.totalElements !== undefined) totalElements = Number(p.totalElements);
  for (const r of p.content) rows.push(r);
}

if (totalElements === null) {
  // Skeleton Contract: a sweep with no reconcilable total is DECLARED
  // unreconciled, never quietly accepted.
  throw new Error('Cohort response carried no top-level totalElements — the walk cannot be ' +
    'reconciled. Declaring the sweep unreconciled rather than accepting it.');
}

if (collected !== totalElements) {
  throw new Error('Cohort walk incomplete: collected ' + collected + ' rows but totalElements is ' +
    totalElements + ' (' + pages.length + ' page(s) at size=' + PAGE_SIZE + '). Refusing to score a ' +
    'partial cohort — a short walk passes in silence and audits a fraction of the population.');
}

if (collected === 0) {
  throw new Error('Cohort is EMPTY for this window. Aborting the run. An empty result is never ' +
    '"no findings": a month with zero change-of-status transactions is a broken query, not a ' +
    'clean month (change_of_status_transaction Default Value).');
}

if (collected < COHORT_FLOOR) {
  throw new Error('Cohort of ' + collected + ' rows is below the declared floor of ' + COHORT_FLOOR +
    '. Measured magnitudes: Aug 2026 = 151, Jan = 811, Mar = 664. Aborting. Do NOT lower this ' +
    'floor to match the run — prove the population from a source other than this query first.');
}

// gate 1 evidence for the run row: the filter must not have over-matched. All 151
// August rows carried expense.id 1677 and nothing else when measured.
const expenseIds = [];
for (const r of rows) {
  const id = (r.expense || {}).id;
  if (expenseIds.indexOf(id) === -1) expenseIds.push(id);
}
const foreign = expenseIds.filter(function (id) { return Number(id) !== EXPENSE_ID; });
if (foreign.length) {
  throw new Error('Cohort contains expense ids other than ' + EXPENSE_ID + ': ' + foreign.join(',') +
    '. The expense filter over-matched — refusing to score fines against a base that was never ' +
    'established for those expenses.');
}

return [{
  json: {
    cohort_rows: rows,
    cohort_count: collected,
    total_elements: totalElements,
    pages_fetched: pages.length,
    page_size: PAGE_SIZE,
    cohort_floor: COHORT_FLOOR,
    population_complete: true,
    distinct_expense_ids: expenseIds
  }
}];

// Split Transactions — MV Overstay Fines (v1)
//
// Adapted from the golden's `Split Contracts`: one item per record the check will
// actually enrich, plus the INTAKE gates.
//
// Gates 1 and 2 are enforced HERE, not at scoring time. The Skeleton Contract is
// blunt about why: an identity field that gets interpolated into a URL must be
// non-empty and the record must be filtered OUT OF THE COHORT before any
// enrichment call — a blank one requests the parent path, ERP answers 400
// NumberFormatException on the path segment itself, the error rail catches it, and
// one bad record kills a run that had already spent an hour succeeding. An intake
// gate that runs at scoring time is not a filter, it is a landmine.
const BASE = 575.65;      // change_of_status_base — STATED CONSTANT, never inferred
const EXPENSE_ID = 1677;

const src = $input.first().json;
const rows = Array.isArray(src.cohort_rows) ? src.cohort_rows : [];

const out = [];
const excluded = {
  out_of_scope_expense: 0,
  no_overstay_at_base: 0,
  amount_unreadable: 0,
  date_missing: 0,
  txn_id_missing: 0
};
const unclassifiable = [];

for (const r of rows) {
  const id = r.id;
  const amountRaw = r.amount;
  const amount = (amountRaw === '' || amountRaw === null || amountRaw === undefined)
    ? null : Number(amountRaw);
  const expenseId = (r.expense || {}).id;

  // No id, no enrichment call. This is the URL-path guard, not a nicety.
  if (id === '' || id === null || id === undefined) {
    excluded.txn_id_missing += 1;
    unclassifiable.push({ why: 'txn_id_missing', date: r.date || '', amount: amountRaw });
    continue;
  }

  // gate 1 — population is expense.id 1677 for the period, and NOTHING else.
  // NEVER widen the expense filter to find more cases: renewal and cancellation
  // immigration expenses carry a different base that has not been established, so
  // including them would compute fines against the wrong constant. And out of
  // scope is NEVER reported as clean — the excluded counts are published.
  if (Number(expenseId) !== EXPENSE_ID) { excluded.out_of_scope_expense += 1; continue; }

  // overstay_txn_date Default Value: missing = exclude from the period and report
  // as unclassifiable, NEVER silently include.
  if (!r.date) {
    excluded.date_missing += 1;
    unclassifiable.push({ why: 'date_missing', txn_id: String(id), amount: amountRaw });
    continue;
  }

  // gate 2 — overstay exists ONLY where the amount exceeds the base. At exactly
  // 575.65 there is no overstay and the transaction leaves the check with no case.
  //
  // NEVER treat a missing or unreadable amount as the base: that silently means
  // "no overstay" and drops a real case. It goes to review instead, which means it
  // must still travel down the pipeline — so it is emitted, not filtered.
  if (amount === null || !Number.isFinite(amount)) {
    excluded.amount_unreadable += 1;
    out.push({
      json: {
        case_key: String(id), txn_id: String(id), txn_date: r.date || '',
        txn_amount: null, txn_vat_amount: r.vatAmount === undefined ? null : r.vatAmount,
        expense_id: expenseId, skip_computation: false,
        // Identity rides on the cohort row now - see Verify Cohort Pull. Carried on the
        // unreadable-amount path too, so a review case still names its person.
        housemaids: Array.isArray(r.housemaids) ? r.housemaids : [],
        enrich_blocked: 'txn_amount_unreadable',
        enrich_blocked_text: 'Transaction amount missing or unreadable — routed to review. ' +
          'Never assumed to be the base, which would silently mean "no overstay".'
      }
    });
    continue;
  }

  if (amount <= BASE) { excluded.no_overstay_at_base += 1; continue; }

  out.push({
    json: {
      case_key: String(id),
      txn_id: String(id),
      txn_date: r.date,
      txn_amount: amount,
      txn_vat_amount: r.vatAmount === undefined ? null : r.vatAmount,
      expense_id: expenseId,
      // Carried, not looked up. The legacy advancesearch route projects housemaids[] with the
      // population, so `Attach Identity` reads it from here instead of from a per-transaction
      // detail call. Same gate-3 contract - housemaids[0].housemaid.id and nothing else.
      housemaids: Array.isArray(r.housemaids) ? r.housemaids : [],
      over_base_aed: Math.round((amount - BASE) * 100) / 100,
      skip_computation: false,
      // The list payload's clientId / contractId / paymentId are EMPTY STRINGS on
      // every row and clients[] / contracts[] are empty arrays (measured 30 of 30,
      // 2026-08-12). The ONLY identifier here is `description` free text —
      // "NAME / New Housemaid / Change of Status / DATE / Noqodi-ref" — and it is
      // deliberately NOT carried forward. Never resolve a maid from it, and never
      // join a transaction to a fine by amount, date or name: txn 2076380 (+450)
      // was attributed to maid 65071, who also had a 450 fine, when it belongs to
      // maid 84087. Two maids, same nine-day fine. Identity comes from the cohort
      // row's own housemaids[] link, and only from housemaids[0].housemaid.id.
      _identity_source: 'POST /accounting/transactions/page/advancesearch -> housemaids[0] (inline on the cohort row)'
    }
  });
}

const stats = {
  cohort_count: src.cohort_count,
  pages_fetched: src.pages_fetched,
  population_complete: src.population_complete === true,
  with_overstay: out.filter(function (i) { return i.json.txn_amount !== null; }).length,
  excluded: excluded,
  unclassifiable: unclassifiable
};

if (out.length === 0) {
  // Every transaction sat at exactly the base. That is a real possible month, but
  // it is not the same as an empty cohort, and it must be visible rather than
  // reported as a silent pass.
  return [{ json: { _no_overstay_in_window: true, intake_stats: stats } }];
}

for (const i of out) i.json.intake_stats = stats;
return out;

// Merge with previous_cases — combine in-window transactions with previous_cases.
// Output: one item per case, keyed by case_key (= transaction id as string).
//
// CLONED FROM THE GOLDEN. Everything from "2) previous_cases" to the end is
// byte-for-byte identical to n8n/travel_assist/merge_with_previous_cases.js —
// asserted by tools/assert_clone.py, which fails the build if a character moves.
// That block is the carry-forward and auditor-override handling and is NOT ours to
// re-derive: the pending_flag line alone encodes a regression that has already
// happened once in production.
//
// TWO THINGS DIFFER, both required and both declared:
//   1. Section 1 maps THIS check's cohort. The golden mapped contract rows and kept
//      only `housemaid.travelAssist === true`; this maps change-of-status
//      transactions, whose case key is the transaction id. Nothing else about the
//      cohort is decided here — `Split Transactions` already applied gates 1 and 2.
//   2. `pickPhones()` IS DELETED. The golden collected up to nine client phone
//      numbers onto every case. This check is marked "Handles sensitive data", and
//      phone numbers must never reach a case, a run summary, the portal or an
//      email. There is no phone field anywhere in this flow.
const validated = $('Validate Inputs').first().json;
const params    = validated.params || {};
const prev      = Array.isArray(params.previous_cases) ? params.previous_cases : [];

// Get all transaction rows out of the previous node (Split Transactions).
// Each input item already represents one transaction carrying overstay.
const txnRows = $input.all().map(i => i.json);

const working = new Map(); // case_key -> case object

// case_key -> index of the INPUT item the case was built from.
//
// This node runs Once for All Items, so n8n does NOT auto-assign `pairedItem` the
// way it does for the Run-Once-for-Each-Item nodes further down the chain. Without
// it the item-linking chain is severed here, and `Attach Identity`'s
// `$('Split Transactions').item` throws "Paired item data for item from node
// 'Merge with previous_cases' is unavailable" - which is what happened on the
// first live run that got past intake.
//
// DO NOT "fix" that by swapping `.item` for `.first()` in Attach Identity, which
// is what the n8n error text suggests. `.first()` returns input item 0 for EVERY
// item, so every transaction after the first would be scored against the first
// transaction's carry data and the wrong maid would be attached to the fine -
// silently. That is the exact failure this node's neighbours are written to
// prevent (txn 2076380 was once attributed to maid 65071; it belongs to 84087).
//
// Only in-range cases get an index. A carried-forward case was not fetched this
// run and has NO input item, so it is left unpaired rather than pointed at an
// unrelated transaction - and it carries skip_computation, which routes it away
// from the branch that does the lookup.
const pairedIndex = new Map();

// AUDITOR OVERRIDES. The Security Room lets an admin or auditor reclassify a
// case (manual_override_state, with _by/_at/_reason alongside). That is
// a human decision, and re-scoring the case next run would overwrite it as if it
// had never been made.
//
// green / red are PINNED: the auditor either closed the case or escalated it, so
// the state is kept and the case is not re-scored at all - in range or out.
//
// pending is deliberately NOT pinned. "Pending" means "money is in flight, look
// again next run"; pinning it would freeze the case forever instead of letting
// the next run discover that the payment landed (or bounced). The override is
// still carried through so it stays visible.
const PINNED_OVERRIDES = ['green_flag', 'green_flag_manual', 'red_flag'];

// Minimal case object for a transaction that is NOT in the audit window, so no ERP
// row was fetched for it. Everything the scorer would have filled in stays blank.
function shell(key) {
  return {
    case_key: key,
    txn_id: key,
    txn_date: '',
    txn_amount: null,
    expense_id: 1677,
    maid_id: '',
    maid_name: '',
    contract_id: '',
    previous_state: null,
    carried_state: null,
    manual_override_state: null,
    source: 'carry_forward',
    skip_computation: true
  };
}

// 1) ERP rows in-window. Gates 1 and 2 were applied at intake in Split
// Transactions, so every row arriving here is expense 1677 and carries overstay
// (or is explicitly flagged unreadable and routed to review).
for (let idx = 0; idx < txnRows.length; idx++) {
  const row = txnRows[idx];
  const txnId = String(row.txn_id || '');
  if (!txnId) continue;
  pairedIndex.set(txnId, idx);
  working.set(txnId, Object.assign({}, row, {
    case_key: txnId,
    txn_id: txnId,
    previous_state: null,
    carried_state: null,
    manual_override_state: null,
    source: 'in_range',
    skip_computation: false
  }));
}

// 2) previous_cases — fold in state.
for (const p of prev) {
  if (!p || !p.case_key) continue;
  const key      = String(p.case_key);
  const override = String(p.manual_override_state || '').trim();
  const inRange  = working.has(key);

  // ---- pinned auditor override: wins whether the contract is in range or not ----
  if (override && PINNED_OVERRIDES.indexOf(override) !== -1) {
    const base = inRange ? working.get(key) : shell(key);
    base.previous_state        = p.state || override;
    base.carried_state         = override;
    base.manual_override_state = override;
    base.source                = inRange ? 'manual_override' : 'manual_override_out_of_range';
    base.skip_computation      = true;   // routes to the carry-forward branch
    working.set(key, base);
    continue;
  }

  // ---- in range: scored normally this run ----
  if (inRange) {
    const w = working.get(key);
    w.previous_state = p.state || null;
    // A pending override is not pinned, but keep it visible on the case.
    if (override) w.manual_override_state = override;
    continue;
  }

  // ---- out of range ----
  // Sticky manual greens stay outside the run entirely.
  if (p.state === 'green_flag_manual') continue;

  // red and pending both carry forward without re-evaluation.
  // `pending_flag` MUST be here: a pending case is explicitly NOT settled - its
  // money is scheduled but uncollected - so leaving it out drops the case the
  // moment the audit window moves past its contract start. That regression has
  // already happened once; carried_state is what keeps it from coming back as a
  // red flag downstream.
  if (p.state === 'red_flag' || p.state === 'pending_flag') {
    const s = shell(key);
    s.previous_state        = p.state;
    s.carried_state         = p.state;
    s.manual_override_state = override || null;
    working.set(key, s);
  }
}

const out = Array.from(working.values());
console.log(JSON.stringify({
  stage: 'merge_with_previous_cases',
  total: out.length,
  in_range: out.filter(c => c.source === 'in_range').length,
  carried_forward: out.filter(c => c.source === 'carry_forward').length,
  pinned_overrides: out.filter(c => !!c.manual_override_state && c.skip_computation).length
}));

return out.map(function (c) {
  const item = { json: c };
  const idx = pairedIndex.get(String(c.case_key));
  // Set it only when a real source item exists. An absent pairing is honest; a
  // wrong one is a mis-attributed fine.
  if (idx !== undefined) item.pairedItem = { item: idx };
  return item;
});

// Attach Identity — MV Overstay Fines (v1). Mode: Run Once for Each Item.
//
// gate 3 — identity resolution before ANYTHING else. This runs before any status,
// fine or payment is read, because every later call is keyed on what it produces.
//
// `overstay_txn_maid_id` = housemaids[0].housemaid.id   (.label is a name, display only)
// `overstay_txn_contract_id` = housemaids[0].contractId
//
// 2026-08-30: THE LINK NO LONGER COMES FROM A PER-TRANSACTION DETAIL CALL. The cohort route
// moved to the legacy /accounting/transactions/page/advancesearch, whose projection carries
// housemaids[] inline, so `Split Transactions` puts it on the case and this node reads it from
// there. `Get Transaction Detail` and its `Judge Detail Batch` breaker are deleted. The gate-3
// CONTRACT is unchanged - same field, same position, same refusal to infer - only its source
// moved upstream, and one ERP call per over-base transaction disappeared with it.
//
// The detail-read-failed branch that used to sit here is gone with the call it described. There
// is no longer a fetch that can fail between the cohort and this node; a row either carried a
// housemaids[] link or it did not, and that is the one distinction left to make.
//
// NEVER resolve a maid from the transaction `description`, even though it contains
// her name. NEVER join a transaction to a fine by amount, by date, or by name —
// that already produced a false link during the build: txn 2076380 (+450) was
// attributed to maid 65071, who also had a 450 fine, when it belongs to maid 84087.
//
// The cohort row's own top-level contractId and clientId are EMPTY STRINGS and
// clients[] / contracts[] are empty arrays — measured on 30 of 30 payloads, 2026-08-12.
// Only the nested housemaids[0] fields are populated. The client is reached through the
// contract, never directly off the transaction.
const carry = $('Split Transactions').item.json;

const out = Object.assign({}, carry);

// The case row IS the identity source now. Reading `carry` rather than `$json` states which one
// is meant, so a node inserted between here and Split Transactions cannot silently change what
// this gate sees.
const hms = Array.isArray(carry.housemaids) ? carry.housemaids : null;

if (!hms || hms.length === 0) {
  // gate 3 Default Value: absent or empty housemaids[] routes to review
  // UNATTRIBUTED. It is emitted, not dropped — but it must NOT reach the fines or
  // payments calls, because interpolating an empty id into a URL path makes ERP
  // answer 400 on the path segment and kills the whole run.
  out.maid_id = '';
  out.contract_id = '';
  out.maid_name = '';
  out.identity_resolved = false;
  out.enrich_blocked = 'unattributed';
  out.enrich_blocked_text = 'The cohort row carried no housemaids[] entry, so the fine cannot ' +
    'be attributed to a person. Routed to review unattributed. The description free text ' +
    'contains a name and was deliberately not used.';
  return { json: out };
}

const h0 = hms[0] || {};
const maid = h0.housemaid || {};
const maidId = (maid.id === '' || maid.id === null || maid.id === undefined) ? '' : String(maid.id);
const contractId = (h0.contractId === '' || h0.contractId === null || h0.contractId === undefined)
  ? '' : String(h0.contractId);

out.maid_id = maidId;
out.maid_name = String(maid.label || '');
out.contract_id = contractId;
out.housemaids_len = hms.length;

if (!maidId) {
  out.identity_resolved = false;
  out.enrich_blocked = 'unattributed';
  out.enrich_blocked_text = 'housemaids[0].housemaid.id is empty — no authoritative link from ' +
    'the transaction to a person. Routed to review unattributed.';
  return { json: out };
}

if (!contractId) {
  // overstay_txn_contract_id Default Value: empty routes to review; without it
  // recovery cannot be checked and MUST NOT be assumed zero.
  out.identity_resolved = false;
  out.enrich_blocked = 'contract_id_missing';
  out.enrich_blocked_text = 'housemaids[0].contractId is empty, so recovery cannot be checked. ' +
    'Routed to review — recovery is never assumed to be zero.';
  return { json: out };
}

out.identity_resolved = true;
return { json: out };

// Attach Fines — MV Overstay Fines (v1). Mode: Run Once for Each Item.
//
// GET /visa/overstay-fines/housemaid/{maid_id} returns a LIST, not an object.
//
// This node only NORMALISES. It does not decide: the placeholder filter (gate 5),
// the days x 50 reconciliation (gate 6), the waiver (gate 9) and the threshold
// (gate 7) all belong to `Compute Case States`, in the order the policy page lists
// them. Splitting the decisions across two nodes is how a gate ends up running out
// of order without anyone being able to see it.
//
// `overstayFinesStatus` and `datePaid` are captured for context and are NEVER
// gated on. Measured live 2026-08-12: `datePaid` is empty on every fine read, and
// `overstayFinesStatus` tracks the WAIVER (Pending 24 / Partially Waived 2 / Fully
// Waived 2), not the collection — maid 137261 is paid in full and still reads
// `Pending`. Gating on either would close real findings.
//
// `housemaid.phoneNumber` arrives already masked as '***' and is dropped anyway:
// this check handles sensitive data, and phone numbers never reach a case, a run
// summary, the portal or an email.
const fetched = $input.item.json;
const carry = $('Attach Identity').item.json;
const out = Object.assign({}, carry);

// The failed-read branch, kept separate from the shape branch below so the review note names
// the real cause. `fullResponse` is on, so a success always carries `body`; an n8n error item
// carries `error` and no body at all.
if (fetched && fetched.error !== undefined && fetched.error !== null &&
    !Array.isArray(fetched.body)) {
  const e = fetched.error;
  out.fines = [];
  out.fines_read = false;
  out.enrich_blocked = 'fines_unread';
  out.enrich_blocked_text = 'The OS-fines read FAILED: ' +
    String((e && e.message) || e).slice(0, 300) + ' — routed to review. A read that did not ' +
    'happen is never verifier rule 15 ("no fine on her OS tab"), which is a real finding, and ' +
    'is never clean.';
  return { json: out };
}

// `Get Overstay Fines` runs with onError: continueRegularOutput as of 2026-08-23. This comment
// used to say the node ran with continueErrorOutput and that a failed read "goes down the error
// rail rather than arriving here". That is no longer true, and a stale sentence about error
// routing is the kind that makes the next reader stop checking the parameter. The node was
// changed so `Judge Fines Batch` can COUNT its failures (ERP-LOAD-POLICY.md §5): routing them
// away would leave the breaker counting successes only, and a breaker that cannot see a failure
// is worse than none because its green gets quoted.
//
// So two different things can arrive here now: a read that FAILED, carrying `error`, and the
// older case of a successful call that returned something other than a list. Unread is not the
// same as absent and must stay distinguishable: an empty list is verifier rule 15 (a real
// finding), whereas an unread or unreadable response is a review item.
//
// `.body` IS THE LIVE SHAPE and must stay first. The endpoint returns a BARE JSON
// array, and n8n's HTTP Request node splits a top-level array into one item per
// element — so this node used to receive a single fine OBJECT, the list guard
// below fired, and all 29 cases of run 85011 landed `fines_unreadable`. Two
// quieter consequences were worse than the block: a maid with NO fines produced
// zero items and vanished from the run entirely (maids 17542 and 84087 did), and
// a maid with two fines produced two (test case 130141). `Get Overstay Fines` now
// sets fullResponse, so the array arrives nested under `body` and there is no
// top-level array to split — exactly one item per maid for 0, 1 or N fines.
// The bare-array branch is kept: it is the shape if fullResponse is ever removed.
let rows = null;
if (fetched && Array.isArray(fetched.body)) rows = fetched.body;
else if (Array.isArray(fetched)) rows = fetched;
else if (fetched && Array.isArray(fetched.data)) rows = fetched.data;
else if (fetched && Array.isArray(fetched.content)) rows = fetched.content;

if (rows === null) {
  const isEmptyObject = fetched && typeof fetched === 'object' && Object.keys(fetched).length === 0;
  if (isEmptyObject) {
    // n8n renders an empty JSON array response as {} on some response formats.
    // Treat it as an empty list: that is rule 15, not an unreadable payload.
    out.fines = [];
    out.fines_read = true;
    return { json: out };
  }
  out.fines = [];
  out.fines_read = false;
  out.enrich_blocked = 'fines_unreadable';
  out.enrich_blocked_text = 'The OS-fines endpoint did not return a list. keys=' +
    Object.keys(fetched || {}).join(',') + ' — routed to review. An unreadable response is NOT ' +
    'the same as "no fine on her OS tab" and must not be scored as either clean or unexplained.';
  return { json: out };
}

out.fines_read = true;
out.fines = rows.map(function (f) {
  const hm = f.housemaid || {};
  return {
    fine_id: f.id === undefined ? '' : String(f.id),
    gross: f.originalOverstayFees,          // overstay_fine_gross — context ONLY
    net: f.overstayFineAmount,              // overstay_fine_net  — THE EXPECTATION
    reduced: f.reducedAmount,               // '' when there is no waiver
    days: f.numOfOverstayDays,
    reduction_reason: f.reductionReason,     // OBJECT {id,label} when waived, '' when not
    fines_status_context: f.overstayFinesStatus || '',   // never gated on
    date_paid_context: f.datePaid || '',                 // never gated on; empty on every read
    housemaid_type: hm.housemaidType || ''   // 'MaidVisa' on every row measured
  };
});
out.fines_count_raw = out.fines.length;

return { json: out };

parameters.jsonBody:
={{ JSON.stringify([
  { property: "contract.id", operation: "=", value: $json.contract_id },
  { property: "typeOfPayment.id", operation: "=", value: "8610" }
]) }}

parameters.jsCode:
// Attach Payments — MV Overstay Fines (v1). Mode: Run Once for Each Item.
//
// gate 10 — recovery is the sum of RECEIVED overstay-fee payments on the contract.
// This node normalises the rows and, critically, records whether the result was
// COMPLETE. `Compute Case States` refuses to conclude anything from a truncated
// one.
//
// BOTH FILTERS ARE REQUIRED and they live on the HTTP node: contract.id AND
// typeOfPayment.id = 8610. Measured live 2026-08-12 on contract 1101801 — with
// contract.id alone the search returns 40 rows of totalElements 599, every one of
// them `monthly_payment`, and shows zero overstay payments. That reads as "never
// billed" and it is false. This node asserts completeness so that failure mode
// cannot reach a verdict.
//
// DO NOT FOLLOW THE `replaced` FLAG to chain payments. On contract 1100875 a
// DELETED 1,250 is followed by a RECEIVED 250 with replaced = false on BOTH,
// because it is a re-bill after a waiver, not a partial payment. Confirmed live.
// Every overstay-fee row on the contract is summed instead.
//
// `vat` is 0.0 and `vatPaidByClient` false on 20 of 20 rows measured, so there is
// no VAT on this line and raw amounts are compared. Per the Skeleton Contract no
// VAT rate is hardcoded anywhere — the value is read off each row and carried.
const TYPE_ID = 8610;         // typeOfPayment.code = overstay_fee
const fetched = $input.item.json;
const carry = $('Attach Fines').item.json;
const out = Object.assign({}, carry);

// `Get Overstay Payments` runs with onError: continueRegularOutput as of 2026-08-23, so that
// `Judge Payments Batch` can COUNT its failures (ERP-LOAD-POLICY.md §5). A read that FAILED
// arrives here carrying `error` and no `content`, and it is caught first so the review note says
// the search failed rather than that it returned an unexpected shape. The distinction matters
// more here than anywhere else in this flow: an unread payment search reads as "never billed",
// which is the exact false clean this node was written to prevent.
if (fetched && fetched.error !== undefined && fetched.error !== null &&
    !Array.isArray(fetched.content)) {
  const e = fetched.error;
  out.payments = [];
  out.payments_complete = false;
  out.enrich_blocked = out.enrich_blocked || 'payments_unread';
  out.enrich_blocked_text = out.enrich_blocked_text ||
    ('The overstay-fee payment search FAILED: ' + String((e && e.message) || e).slice(0, 300) +
     ' — routed to review. Never read as nothing recovered.');
  return { json: out };
}

const body = (fetched && typeof fetched === 'object') ? fetched : {};
const content = Array.isArray(body.content) ? body.content : null;

if (content === null) {
  out.payments = [];
  out.payments_complete = false;
  out.enrich_blocked = out.enrich_blocked || 'payments_unreadable';
  out.enrich_blocked_text = out.enrich_blocked_text ||
    ('The overstay-fee payment search returned no `content` array. keys=' +
     Object.keys(body).join(',') + ' — routed to review. Never read as nothing recovered.');
  return { json: out };
}

const total = body.totalElements === undefined ? null : Number(body.totalElements);
out.payments_total_elements = total;
out.payments_returned = content.length;
out.payments_complete = (total !== null && content.length === total);

out.payments = content
  // The HTTP filter already scopes to 8610; this is a second, cheap assertion that
  // the filter was actually applied. A row of another type here means the request
  // body was changed and the "both filters" trap is live again.
  .filter(function (p) {
    const tp = p.typeOfPayment || {};
    return Number(tp.id) === TYPE_ID;
  })
  .map(function (p) {
    return {
      payment_id: p.id === undefined ? '' : String(p.id),
      amount: p.amountOfPayment,
      status: (p.status || {}).value || '',
      replaced: p.replaced === true,      // captured, deliberately NOT followed
      vat: p.vat,
      vat_paid_by_client: p.vatPaidByClient === true,
      type_code: (p.typeOfPayment || {}).code || ''
    };
  });

out.payments_foreign_type = content.length - out.payments.length;
if (out.payments_foreign_type > 0) {
  out.payments_complete = false;
  out.enrich_blocked = out.enrich_blocked || 'payments_filter_not_applied';
  out.enrich_blocked_text = out.enrich_blocked_text ||
    (out.payments_foreign_type + ' of ' + content.length + ' rows are not typeOfPayment 8610 — ' +
     'the typeOfPayment filter was not applied. With contract.id alone this search returns ' +
     'unrelated monthly payments and no overstay row at all, which reads as "never billed" and ' +
     'is false. Routed to review.');
}

return { json: out };

// Compute Case States — MV Overstay Fines (v1)
//
// SOURCE OF TRUTH: E:/Claude Code/n8n/mv_overstay_fines/compute_case_states.js
// Push with push_nodes.py; never edit only in the n8n UI.
//
// CHECK TYPE: Money in. A finding is observed BELOW expected. The arithmetic is
// never reversed here and no residue is ever added to what the client owes.
//
// The twelve deterministic gates of "Audit Conditional Policy — MV Maid ->
// MV Overstay Fines" run in the order that page lists them. That order is part of
// the rule: gate 9 (the structured waiver) CHANGES the expectation and therefore
// runs BEFORE gate 10 tests the remaining gap. If the gap were tested first, a
// fine of 1,250 gross that had been waived down to a net 250 and paid at 250
// would read as an 1,000 shortfall, and the clearance would be silent.
//
// Gates 1 and 2 are INTAKE gates and are enforced in `Split Transactions`, not
// here — a record excluded at scoring time is not filtered, it is a landmine
// (Skeleton Contract, Intake adapter).
//
// NO GAP TOLERANCE IS APPLIED. The check's own pages declare none, and none may
// be borrowed from another check or from the golden workflow. round2() below
// exists only to defeat IEEE-754 noise on sums of AED cents; it is not a
// tolerance and must not be turned into one.
const BASE = 575.65;                 // change_of_status_base — STATED CONSTANT
const FINE_PER_DAY = 50;             // gate 6
const THRESHOLD = 300;               // gate 7 — MV only. CC's is 200. NEVER share.
const EXPENSE_ID = 1677;             // gate 1

// Skeleton Contract, Payment lifecycle. RECEIVED settles; these are dead;
// EVERYTHING ELSE — including PRE_PDP, PDC and any unknown value — is in flight.
// That open end is a deliberate fail-safe (gate 11) and must never be closed
// into a fixed list.
const DEAD_STATUSES = ['DELETED', 'BOUNCED', 'CANCELLED', 'REJECTED', 'FAILED', 'REFUSED', 'VOID'];

function round2(n) { return Math.round((Number(n) || 0) * 100) / 100; }

function num(v) {
  // '' / null / undefined are ABSENT, not zero. Reading an absent net fine as 0
  // would say "nothing owed" and close a real finding green.
  if (v === '' || v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function lifecycle(status) {
  const u = String(status || '').toUpperCase();
  if (u === 'RECEIVED') return 'collected';
  if (DEAD_STATUSES.indexOf(u) !== -1) return 'dead';
  return 'in_flight';
}

// gate 9 — reductionReason is an OBJECT {id,label} when a waiver exists and the
// EMPTY STRING when it does not (measured live 2026-08-12: 24 unwaived rows carry
// '', 4 waived rows carry the object). Reading it as text writes [object Object]
// into a case and the reviewer sees no reason at all; reading .label off the
// empty string yields undefined. Both shapes are handled.
function reductionLabel(rr) {
  if (rr && typeof rr === 'object') return String(rr.label || '').trim();
  if (typeof rr === 'string') return rr.trim();
  return '';
}

const VERDICT_WORDS = {
  red: 'There is findings',
  green: 'Good',
  pending: 'Awaiting collection',
  escalated: 'Escalated, awaiting update'
};

const items = $input.all().map(function (i) { return i.json; });
const out = [];
const runStats = {
  txns_in: 0,
  carried_forward: 0,
  enrich_blocked: 0,
  placeholders_dropped: 0,
  fines_scored: 0,
  data_quality_flags: 0,
  sub300_absorbed: 0,
  sub300_collected_count: 0,
  sub300_collected_aed: 0,
  residue_count: 0,
  residue_aed: 0,
  no_fine_record: 0,
  states: { red: 0, green: 0, pending: 0, green_manual: 0 }
};

function emit(base, extra) {
  const c = Object.assign({}, base, extra);
  c.verdict_word = c.state === 'red' ? VERDICT_WORDS.red
    : c.state === 'pending' ? (c.escalated ? VERDICT_WORDS.escalated : VERDICT_WORDS.pending)
      : VERDICT_WORDS.green;
  const k = c.state === 'green_manual' ? 'green_manual' : c.state;
  if (runStats.states[k] !== undefined) runStats.states[k] += 1;
  out.push(c);
  return c;
}

for (const it of items) {
  runStats.txns_in += 1;

  // ---- carry-forward / auditor override -------------------------------------
  // Skeleton: out-of-window red and pending cases are carried forward WITHOUT
  // being re-scored, and pinned overrides are never re-scored. `Merge with
  // previous_cases` already decided this; re-deciding it here would overwrite a
  // human's judgement.
  if (it.skip_computation === true) {
    runStats.carried_forward += 1;
    emit(it, { scored: false, carried_forward: true });
    continue;
  }

  const shared = {
    case_key: String(it.case_key || it.txn_id || ''),
    txn_id: it.txn_id === undefined ? '' : String(it.txn_id),
    txn_date: it.txn_date || '',
    txn_amount: num(it.txn_amount),
    txn_vat_amount: num(it.txn_vat_amount),
    expense_id: it.expense_id,
    maid_id: it.maid_id === undefined || it.maid_id === null ? '' : String(it.maid_id),
    maid_name: it.maid_name || '',
    contract_id: it.contract_id === undefined || it.contract_id === null ? '' : String(it.contract_id),
    manual_override_state: it.manual_override_state || '',
    scored: true,
    carried_forward: false
  };

  // gate 1 — belt and braces. Split Transactions already filtered on this; a
  // second expense id arriving here means the cohort request changed.
  if (Number(shared.expense_id) !== EXPENSE_ID) {
    emit(shared, {
      state: 'pending', escalated: true, bill_client: false,
      expected_aed: null, received_aed: null, gap_aed: null,
      reason_code: 'out_of_scope_expense',
      reason_text: 'Expense ' + shared.expense_id + ' is not ' + EXPENSE_ID +
        '. Out of scope for this check, and out of scope is NEVER reported as clean.'
    });
    continue;
  }

  // ---- enrichment could not complete ---------------------------------------
  // gate 3 default: absent or empty housemaids[] routes to review UNATTRIBUTED.
  // Never fall back to the transaction description, even though it holds a name.
  if (it.enrich_blocked) {
    runStats.enrich_blocked += 1;
    emit(shared, {
      state: 'pending', escalated: true, bill_client: false,
      expected_aed: null, received_aed: null, gap_aed: null,
      reason_code: it.enrich_blocked,
      reason_text: it.enrich_blocked_text ||
        'Enrichment could not complete, so no expectation could be established. Never scored as clean.'
    });
    continue;
  }

  // gate 2 default — a missing or unreadable amount is NOT the base. Treating it
  // as the base silently means "no overstay" and drops a real case.
  if (shared.txn_amount === null) {
    emit(shared, {
      state: 'pending', escalated: true, bill_client: false,
      expected_aed: null, received_aed: null, gap_aed: null,
      reason_code: 'txn_amount_unreadable',
      reason_text: 'Transaction amount missing or unreadable — routed to review, never assumed to be the base.'
    });
    continue;
  }

  const payments = Array.isArray(it.payments) ? it.payments : [];
  const paymentsComplete = it.payments_complete === true;
  let received = 0, inFlight = 0, dead = 0;
  const statusesSeen = [];
  for (const p of payments) {
    const life = lifecycle(p.status);
    const amt = Number(p.amount) || 0;
    if (statusesSeen.indexOf(String(p.status || '?')) === -1) statusesSeen.push(String(p.status || '?'));
    if (life === 'collected') received += amt;
    else if (life === 'in_flight') inFlight += amt;
    else dead += amt;
  }
  received = round2(received); inFlight = round2(inFlight); dead = round2(dead);

  // gate 5 — placeholder fine rows are discarded BEFORE scoring. Maid 130141
  // carries one; counting it manufactures a phantom case on every run, forever.
  const rawFines = Array.isArray(it.fines) ? it.fines : [];
  const fines = [];
  for (const f of rawFines) {
    const net = num(f.net), days = num(f.days);
    if (round2(net) === 0 && round2(days) === 0) { runStats.placeholders_dropped += 1; continue; }
    fines.push(f);
  }

  // verifier rule 15 — we paid a fine that has no record on the maid's OS-fines
  // tab. This is NOT clean: there is no authoritative amount, so nothing is
  // billed, and it is not buried either. The reviewer's own words on this shape
  // were "something is wrong here".
  if (fines.length === 0) {
    runStats.no_fine_record += 1;
    const overBase = round2(shared.txn_amount - BASE);
    emit(shared, {
      state: 'red', bill_client: false, unexplained: true,
      fine_gross: null, fine_net: null, expected_aed: null,
      received_aed: received, in_flight_aed: inFlight, dead_aed: dead,
      gap_aed: null, over_base_aed: overBase,
      payments_complete: paymentsComplete, statuses_seen: statusesSeen.join(','),
      client_was_asked: payments.length > 0,
      needs_verifier: true, verifier_rule: 'no_os_fines_record',
      reason_code: 'no_os_fines_record',
      reason_text: 'Change-of-status transaction carried AED ' + overBase +
        ' above the base of ' + BASE + ' but the maid\'s OS-fines record shows no matching fine. ' +
        'Unexplained — nothing is billed to the client, because the expectation comes from the ' +
        'OS-fines record and there is not one.'
    });
    continue;
  }

  // One case per SURVIVING fine row (gate 5). Case keys stay txn-level while a
  // transaction yields a single scored fine — which is every live case measured
  // on 2026-08-12 — so carry-forward keying is unchanged. A transaction with two
  // real fines suffixes the fine id to keep the keys distinct.
  const multi = fines.length > 1;

  for (const f of fines) {
    runStats.fines_scored += 1;
    const gross = num(f.gross), net = num(f.net), days = num(f.days);
    const reduced = num(f.reduced);
    const reasonLabel = reductionLabel(f.reduction_reason);
    const key = multi ? shared.case_key + ':' + String(f.fine_id || runStats.fines_scored) : shared.case_key;

    const c = Object.assign({}, shared, {
      case_key: key,
      fine_id: f.fine_id === undefined ? '' : String(f.fine_id),
      fine_gross: gross, fine_net: net, overstay_days: days,
      reduced_amount: reduced, reduction_reason: reasonLabel,
      housemaid_type: f.housemaid_type || '',
      received_aed: received, in_flight_aed: inFlight, dead_aed: dead,
      payments_complete: paymentsComplete,
      statuses_seen: statusesSeen.join(','),
      bill_client: false, needs_verifier: false
    });

    // Default Value on overstay_fine_net / _gross / overstay_days: missing routes
    // to review, NEVER 0. Zero would read as nothing owed.
    if (net === null || gross === null || days === null) {
      emit(c, {
        state: 'pending', escalated: true, expected_aed: null, gap_aed: null,
        reason_code: 'fine_fields_missing',
        reason_text: 'OS-fines row is missing ' +
          [net === null ? 'overstayFineAmount' : null,
            gross === null ? 'originalOverstayFees' : null,
            days === null ? 'numOfOverstayDays' : null].filter(Boolean).join(' / ') +
          ' — routed to review, never read as zero.'
      });
      continue;
    }

    // gate 6 — the fine must reconcile to fifty dirhams a day. A mismatch is a
    // DATA-QUALITY flag and the case still proceeds on the net fine. Never
    // silently correct the fine, and never substitute days x 50 for the net.
    const daysX50Ok = round2(gross) === round2(days * FINE_PER_DAY);
    if (!daysX50Ok) runStats.data_quality_flags += 1;
    c.days_x50_ok = daysX50Ok;
    c.data_quality = daysX50Ok ? '' :
      'originalOverstayFees ' + gross + ' != numOfOverstayDays ' + days + ' x ' + FINE_PER_DAY +
      ' (= ' + round2(days * FINE_PER_DAY) + ')';

    // gate 12 — the residue above base plus GROSS fine. Mentioned on the case and
    // on its own report line. NEVER a red flag, never added to what the client is
    // asked to pay, never rounded away. Owner's ruling 2026-08-12.
    const residue = round2(c.txn_amount - BASE - gross);
    c.residue_aed = residue > 0 ? residue : 0;
    if (residue > 0) { runStats.residue_count += 1; runStats.residue_aed = round2(runStats.residue_aed + residue); }

    // gate 9 — the structured waiver reduces or clears the expectation BEFORE any
    // comparison. Never handed to the AI verifier: 19 of 20 findings in the last
    // manual run were waived and visible right here.
    if (reduced !== null && reduced > 0 && reasonLabel === '') {
      emit(c, {
        state: 'pending', escalated: true, expected_aed: null, gap_aed: null,
        reason_code: 'waiver_without_reason',
        reason_text: 'reducedAmount ' + reduced + ' is set but reductionReason is empty — routed to review.'
      });
      continue;
    }
    if (round2(net) === 0) {
      emit(c, {
        state: 'green', expected_aed: 0, gap_aed: 0, threshold_applies: false,
        reason_code: 'waived',
        reason_text: 'Fine of ' + gross + ' fully waived' +
          (reduced === null ? '' : ' (reducedAmount ' + reduced + ')') +
          (reasonLabel ? ' — reason: ' + reasonLabel : '') +
          '. Nothing owed, nothing to collect.' +
          (residue > 0 ? ' Residue of AED ' + residue + ' above base + fine is mentioned, not flagged.' : '')
      });
      continue;
    }

    // gate 7 — three hundred dirhams is a TRIGGER, not a deductible. At or above
    // 300 the client owes the WHOLE fine; below 300 the company absorbs the WHOLE
    // fine. There is no remainder arithmetic anywhere in this check.
    const thresholdApplies = net >= THRESHOLD;
    const expected = thresholdApplies ? round2(net) : 0;
    c.threshold_applies = thresholdApplies;
    c.expected_aed = expected;
    if (!thresholdApplies) runStats.sub300_absorbed += 1;

    // gate 10 — recovery is the sum of RECEIVED overstay-fee rows on the contract.
    // Never conclude "nothing recovered" from a truncated result.
    if (!paymentsComplete) {
      emit(c, {
        state: 'pending', escalated: true, gap_aed: null,
        reason_code: 'payments_truncated',
        reason_text: 'The overstay-fee payment search did not return a complete result ' +
          '(content.length != totalElements), so recovery is unknown. Never read as nothing recovered.'
      });
      continue;
    }

    const shortfall = round2(Math.max(0, expected - received));
    c.gap_aed = shortfall;

    // gate 8 — a sub-300 fine the client paid anyway. Clean, and listed on its own
    // report line. Never a red flag; never dropped silently either.
    const sub300Collected = !thresholdApplies && received > 0;
    c.sub300_client_paid = sub300Collected;
    if (sub300Collected) {
      runStats.sub300_collected_count += 1;
      runStats.sub300_collected_aed = round2(runStats.sub300_collected_aed + received);
    }

    // gate 11 — raised but unsettled is PENDING, not a finding. Never scored as
    // unrecovered (the client HAS been asked) and never counted toward recovery.
    if (inFlight > 0) {
      emit(c, {
        state: 'pending',
        reason_code: 'payment_in_flight',
        reason_text: 'AED ' + inFlight + ' of overstay fee is raised but not settled (' +
          statusesSeen.join(', ') + '). Expected ' + expected + ', received ' + received +
          '. The client has been asked; nobody has failed yet.' +
          (sub300Collected ? ' Fine is under ' + THRESHOLD + ' — the company absorbs it, so this collection is tracked, not scored.' : '') +
          (residue > 0 ? ' Residue AED ' + residue + ' mentioned.' : '')
      });
      continue;
    }

    if (shortfall > 0) {
      emit(c, {
        state: 'red', bill_client: true, needs_verifier: true,
        reason_code: 'not_recovered',
        reason_text: 'Fine net ' + net + ' (gross ' + gross + ' over ' + days + ' days' +
          (reduced !== null && reduced > 0 ? ', waived ' + reduced + (reasonLabel ? ' — ' + reasonLabel : '') : '') +
          '). Client owes ' + expected + ' in full; AED ' + received + ' RECEIVED' +
          (dead > 0 ? ', AED ' + dead + ' on dead rows (' + statusesSeen.join(', ') + ')' : '') +
          '. Shortfall AED ' + shortfall + ' not recovered.' +
          (residue > 0 ? ' Residue AED ' + residue + ' above base + fine is mentioned, never billed.' : '')
      });
      continue;
    }

    emit(c, {
      state: 'green',
      reason_code: sub300Collected ? 'sub300_client_paid'
        : (thresholdApplies ? 'recovered' : 'absorbed_under_threshold'),
      reason_text: thresholdApplies
        ? ('Expected ' + expected + ', received ' + received + ' RECEIVED. Recovered in full.' +
           (residue > 0 ? ' Residue AED ' + residue + ' mentioned.' : ''))
        : ('Fine net ' + net + ' is under ' + THRESHOLD + ' — the company absorbs the whole fine, so nothing is expected from the client.' +
           (sub300Collected ? ' The client paid AED ' + received + ' anyway: tracked and mentioned, never scored.' : '') +
           (residue > 0 ? ' Residue AED ' + residue + ' mentioned.' : ''))
    });
  }
}

return [{ json: { cases: out, run_stats: runStats } }];

// Adjudicate Cases — MV Overstay Fines (v1)
//
// The deterministic gate between scoring and publishing. `Compute Case States`
// answers "is money missing?"; this answers "is that actionable, and what does a
// human need to see?".
//
// It NEVER re-derives an expectation. It reads the figures Compute Case States
// already published, so it is structurally incapable of disagreeing with the
// scoring it is gating. Anything that needed an amount was decided upstream.
//
// The three report lines the check page asks for are assembled here:
//   * red flags
//   * fines under AED 300 that the client paid anyway   (gate 8 — MENTION)
//   * residue above base + fine                          (gate 12 — MENTION)
//   * pending
const THRESHOLD = 300;

function round2(n) { return Math.round((Number(n) || 0) * 100) / 100; }

const input = $input.first().json;
const cases = Array.isArray(input.cases) ? input.cases : [];
const stats = input.run_stats || {};

const summary = {
  cases_scored: 0,
  red: 0, green: 0, pending: 0, green_manual: 0,
  carried_forward: 0,
  outstanding_aed: 0,
  sub300_collected_count: 0, sub300_collected_aed: 0,
  residue_count: 0, residue_aed: 0,
  data_quality_flags: 0,
  no_fine_record: 0,
  unattributed: 0,
  to_verifier: 0
};

const lines = { red: [], sub300_collected: [], residue: [], pending: [], data_quality: [] };

for (const c of cases) {
  const state = c.state || 'pending';
  if (c.carried_forward) { summary.carried_forward += 1; continue; }
  summary.cases_scored += 1;

  if (state === 'red') summary.red += 1;
  else if (state === 'green') summary.green += 1;
  else if (state === 'green_manual') summary.green_manual += 1;
  else summary.pending += 1;

  // Outstanding money is only ever the RED gap, and only where a client can
  // actually be billed. gate 15's unexplained cases carry gap_aed = null and
  // bill_client = false on purpose: there is no authoritative fine amount to bill,
  // so they must never inflate a total that someone might go and collect.
  if (state === 'red' && c.bill_client === true && c.gap_aed !== null && c.gap_aed !== undefined) {
    summary.outstanding_aed = round2(summary.outstanding_aed + Number(c.gap_aed));
    lines.red.push({
      case_key: c.case_key, txn_id: c.txn_id, maid_id: c.maid_id, contract_id: c.contract_id,
      fine_net: c.fine_net, expected_aed: c.expected_aed, received_aed: c.received_aed,
      gap_aed: c.gap_aed, txn_date: c.txn_date, reason_text: c.reason_text
    });
  }

  if (state === 'red' && c.unexplained === true) {
    summary.no_fine_record += 1;
    lines.red.push({
      case_key: c.case_key, txn_id: c.txn_id, maid_id: c.maid_id, contract_id: c.contract_id,
      fine_net: null, expected_aed: null, received_aed: c.received_aed,
      gap_aed: null, txn_date: c.txn_date, reason_text: c.reason_text,
      bill_client: false
    });
  }

  if (c.reason_code === 'unattributed') summary.unattributed += 1;

  // gate 8 — a fine below three hundred that the client paid anyway. Clean, and on
  // its own line. Never a red flag — the client paying is not a failure to
  // recover. Never dropped silently either: the company collecting what it agreed
  // to absorb is worth a human seeing, which is the whole reason this line exists.
  if (c.sub300_client_paid === true) {
    summary.sub300_collected_count += 1;
    summary.sub300_collected_aed = round2(summary.sub300_collected_aed + Number(c.received_aed || 0));
    lines.sub300_collected.push({
      case_key: c.case_key, maid_id: c.maid_id, contract_id: c.contract_id,
      fine_net: c.fine_net, received_aed: c.received_aed, txn_date: c.txn_date,
      note: 'Fine of ' + c.fine_net + ' is under AED ' + THRESHOLD +
        ' — the company absorbs it, and the client paid ' + c.received_aed + ' anyway.'
    });
  }

  // gate 12 — the residue above base plus fine is MENTIONED, never scored, never
  // added to what the client is asked to pay, never rounded away. Owner's ruling
  // 2026-08-12. Its cause is not established.
  if (Number(c.residue_aed) > 0) {
    summary.residue_count += 1;
    summary.residue_aed = round2(summary.residue_aed + Number(c.residue_aed));
    lines.residue.push({
      case_key: c.case_key, txn_id: c.txn_id, txn_amount: c.txn_amount,
      fine_gross: c.fine_gross, residue_aed: c.residue_aed, vat_amount: c.txn_vat_amount,
      note: 'We paid AED ' + c.residue_aed + ' above base + fine. Mentioned only — its cause is ' +
        'not established, and it is never billed to the client.'
    });
  }

  if (state === 'pending') {
    lines.pending.push({
      case_key: c.case_key, maid_id: c.maid_id, contract_id: c.contract_id,
      expected_aed: c.expected_aed, received_aed: c.received_aed,
      in_flight_aed: c.in_flight_aed, statuses_seen: c.statuses_seen,
      reason_code: c.reason_code, reason_text: c.reason_text
    });
  }

  if (c.data_quality) {
    summary.data_quality_flags += 1;
    lines.data_quality.push({ case_key: c.case_key, note: c.data_quality });
  }

  // Only RED cases go to the verifier, and only the two shapes it can actually
  // resolve: an unrecovered fine (rules 13/14) or a fine with no OS record
  // (rule 15). The structured waiver is NEVER handed to the model — 19 of the 20
  // findings in the last manual run were waived and visible on the record, and
  // leaving that to the agent reproduces that false-positive rate exactly.
  if (state === 'red' && c.needs_verifier === true) summary.to_verifier += 1;
}

summary.overall = summary.red > 0 ? 'findings' : (summary.pending > 0 ? 'pending' : 'clean');

return [{
  json: {
    cases: cases,
    summary: summary,
    report_lines: lines,
    run_stats: stats,
    // Read the population proof from the node that OWNS it, not from whatever
    // survived three transforms. `Split Transactions` stamps intake_stats onto
    // every item it emits, but `Compute Case States` builds fresh case objects and
    // does not carry it, so the old `cases.find(c => c.intake_stats)` below always
    // resolved to {} - and `Build Run Row` then wrote txns_seen 0, txns_pages 0 and
    // population_complete FALSE into the Runs table for a run that had walked 151
    // rows and reconciled. By that column's own rule a false there means "the run
    // must not be trusted", so every run was self-stamping as untrustworthy.
    // .first() is right here: intake_stats is one global fact about the run, not a
    // per-item value.
    intake_stats: (function () {
      try {
        const s0 = $('Split Transactions').first().json.intake_stats;
        if (s0 && typeof s0 === 'object') return s0;
      } catch (e) { /* fall through to the legacy scan */ }
      return (cases.find(function (c) { return c.intake_stats; }) || {}).intake_stats || {};
    })()
  }
}];

// Build Case Payload — MV Overstay Fines (v1)
//
// The results-callback envelope. Its SHAPE is the skeleton's (check_id, run_id,
// result, result_data.cases, report_html, run note); only the display strings and
// the report body are this check's.
//
// SENSITIVE DATA. This check is marked "Handles sensitive data". Per the build
// rules, individual salaries, IBANs, phone numbers and message contents must never
// reach a case, a run summary, the portal or an email. Accordingly:
//   * `housemaid.phoneNumber` is never carried — it is dropped at Attach Fines even
//     though ERP already returns it masked as '***'.
//   * No SMS or WhatsApp log is fetched anywhere in this flow, so no message
//     content exists to leak.
//   * The RUN NOTE and the totals carry counts and sums only.
//   * Per-maid fine amounts stay in the case rows, which are the workbook-role
//     target the check page asks for ("keep per-maid amounts in the workbook").
const input = $input.first().json;
const cases = Array.isArray(input.cases) ? input.cases : [];
const s = input.summary || {};
const lines = input.report_lines || {};
const intake = input.intake_stats || {};
const validated = $('Validate Inputs').first().json;

const now = new Date().toLocaleString('en-AE', {
  timeZone: 'Asia/Dubai', year: 'numeric', month: 'short', day: '2-digit',
  hour: '2-digit', minute: '2-digit'
});

function aed(n) {
  if (n === null || n === undefined) return '—';
  return Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function esc(v) {
  return String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Verdict names, straight from the check page's own table. Never paraphrased.
const VERDICTS = {
  red: 'There is findings', green: 'Good',
  pending: 'Awaiting collection', escalated: 'Escalated, awaiting update'
};

function row(cells) { return '<tr>' + cells.map(function (c) { return '<td>' + c + '</td>'; }).join('') + '</tr>'; }

let html = '';
html += '<h2>MV Overstay Fines — ' + esc(validated.range_start) + ' to ' + esc(validated.range_end) + '</h2>';
html += '<p><em>Money in. A finding is a fine of AED 300 or more that we paid and did not recover ' +
  'from the client, with no waiver on her OS-fines record and nothing in a complaint that explains it. ' +
  'Run ' + esc(validated.run_id) + ', generated ' + esc(now) + ' (Asia/Dubai).</em></p>';

html += '<h3>Population</h3><ul>';
html += '<li>Change-of-status transactions in window (expense 1677 only): <b>' + esc(intake.cohort_count) +
  '</b> across ' + esc(intake.pages_fetched) + ' page(s); walk reconciled to totalElements: <b>' +
  (intake.population_complete ? 'yes' : 'NO') + '</b></li>';
html += '<li>Carrying overstay (amount &gt; 575.65): <b>' + esc(intake.with_overstay) + '</b></li>';
if (intake.excluded) {
  html += '<li>Excluded at intake — no overstay at base: ' + esc(intake.excluded.no_overstay_at_base) +
    ' · other expense: ' + esc(intake.excluded.out_of_scope_expense) +
    ' · unreadable amount: ' + esc(intake.excluded.amount_unreadable) +
    ' · missing date: ' + esc(intake.excluded.date_missing) + '</li>';
}
html += '<li>Cases scored: <b>' + esc(s.cases_scored) + '</b> (' + esc(s.red) + ' finding · ' +
  esc(s.green) + ' good · ' + esc(s.pending) + ' awaiting) · carried forward ' + esc(s.carried_forward) + '</li>';
html += '<li>Outstanding and billable: <b>AED ' + aed(s.outstanding_aed) + '</b></li>';
html += '</ul>';

html += '<p><b>Out of scope</b> — CC maids (their threshold is 200 and it is recovered onto the ' +
  'maid\'s loan, and no constant is shared with that check), whether the day count we paid for is ' +
  'right, and any expense other than 1677. A fine paid under a renewal or cancellation expense is ' +
  'invisible here: that is a stated blind spot, not a clean result.</p>';

if ((lines.red || []).length) {
  html += '<h3>Findings (' + (lines.red || []).length + ')</h3><table border="1" cellpadding="4" cellspacing="0">';
  html += '<tr><th>Case</th><th>Txn</th><th>Date</th><th>Maid</th><th>Contract</th><th>Fine (net)</th>' +
    '<th>Expected</th><th>Received</th><th>Not recovered</th><th>Reason</th></tr>';
  for (const r of lines.red) {
    html += row([esc(r.case_key), esc(r.txn_id), esc(r.txn_date), esc(r.maid_id), esc(r.contract_id),
      aed(r.fine_net), aed(r.expected_aed), aed(r.received_aed),
      r.bill_client === false ? 'not billable' : aed(r.gap_aed), esc(r.reason_text)]);
  }
  html += '</table>';
}

if ((lines.pending || []).length) {
  html += '<h3>Awaiting collection (' + lines.pending.length + ')</h3><table border="1" cellpadding="4" cellspacing="0">';
  html += '<tr><th>Case</th><th>Maid</th><th>Contract</th><th>Expected</th><th>Received</th>' +
    '<th>In flight</th><th>Statuses</th><th>Why</th></tr>';
  for (const r of lines.pending) {
    html += row([esc(r.case_key), esc(r.maid_id), esc(r.contract_id), aed(r.expected_aed),
      aed(r.received_aed), aed(r.in_flight_aed), esc(r.statuses_seen), esc(r.reason_text)]);
  }
  html += '</table>';
}

// gate 8 — its own report line, exactly as the check page asks. Not a finding.
if ((lines.sub300_collected || []).length) {
  html += '<h3>Mention — fines under AED 300 that the client paid anyway (' +
    lines.sub300_collected.length + ')</h3>';
  html += '<p>The company absorbs any fine below AED 300, so none of this was owed. It is listed ' +
    'because collecting what we agreed to absorb is worth a human seeing. It is never a red flag.</p>';
  html += '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Case</th><th>Maid</th>' +
    '<th>Contract</th><th>Fine</th><th>Client paid</th></tr>';
  for (const r of lines.sub300_collected) {
    html += row([esc(r.case_key), esc(r.maid_id), esc(r.contract_id), aed(r.fine_net), aed(r.received_aed)]);
  }
  html += '</table>';
}

// gate 12 — mentioned, never scored.
if ((lines.residue || []).length) {
  html += '<h3>Mention — paid above base + fine (' + lines.residue.length + ')</h3>';
  html += '<p>Transaction amount minus the AED 575.65 base minus the gross fine. Money we paid above ' +
    'the fine itself; its cause is not established. Never a finding, and never added to what the ' +
    'client is asked to pay. Confined to older transactions carrying vatAmount 2.50.</p>';
  html += '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Case</th><th>Txn</th>' +
    '<th>Txn amount</th><th>Gross fine</th><th>Residue</th><th>vatAmount</th></tr>';
  for (const r of lines.residue) {
    html += row([esc(r.case_key), esc(r.txn_id), aed(r.txn_amount), aed(r.fine_gross),
      aed(r.residue_aed), esc(r.vat_amount)]);
  }
  html += '</table>';
}

if ((lines.data_quality || []).length) {
  html += '<h3>Data quality (' + lines.data_quality.length + ')</h3><ul>';
  for (const r of lines.data_quality) html += '<li>' + esc(r.case_key) + ': ' + esc(r.note) + '</li>';
  html += '</ul>';
}

html += '<p><small>Red flags above are <b>provisional</b> until the verifier posts its verdicts on ' +
  'the later agent-review callback, so this note can say more findings than the portal shows. ' +
  'Independent review before delivery: Abdullah Mahdi. Escalation stays manual — this check sends ' +
  'no email.</small></p>';

const note = 'MV Overstay Fines ' + validated.range_start + '..' + validated.range_end +
  ': ' + s.cases_scored + ' cases scored from ' + (intake.cohort_count || 0) + ' change-of-status ' +
  'transactions (' + (intake.with_overstay || 0) + ' carried overstay). ' +
  s.red + ' finding, ' + s.green + ' good, ' + s.pending + ' awaiting collection. ' +
  'Outstanding and billable AED ' + aed(s.outstanding_aed) + '. ' +
  s.sub300_collected_count + ' sub-300 collections mentioned (AED ' + aed(s.sub300_collected_aed) + '), ' +
  s.residue_count + ' residues mentioned (AED ' + aed(s.residue_aed) + '), ' +
  s.no_fine_record + ' with no OS-fines record. ' + s.to_verifier + ' sent to the verifier.';

return [{
  json: {
    check_id: validated.check_id,
    run_id: validated.run_id,
    callback_url: validated.callback_url,
    result: s.overall === 'findings' ? 'findings' : (s.overall === 'pending' ? 'pending' : 'ok'),
    verdict_names: VERDICTS,
    summary: s,
    result_data: { cases: cases, report_lines: lines, intake_stats: intake },
    report_html: html,
    run_note: note,
    generated_at: new Date().toISOString(),
    delivery: (validated.params || {}).delivery || { portal: true }
  }
}];

// Build Case Rows — MV Overstay Fines (v1)
//
// One item per scored case, shaped to the 27 columns of the data table
// "MV Overstay Fines Cases (test)" (id g6TkMPQAZ80y4DL7). Data tables are the
// Skeleton Contract's declared interim delivery target while the portal is
// unavailable, and they are fed off a node that has ALREADY decided, so they stay
// additive: adding or removing a delivery target never alters a finding.
//
// NULL IS NOT ZERO. Where there is no authoritative amount — verifier rule 15's
// "no record on her OS-fines tab", or any case routed to review before an
// expectation existed — the numeric key is OMITTED rather than written as 0.
// Writing 0 into `expected_aed` or `gap_aed` would read as "nothing owed", which
// is the precise failure the Default Value columns on the ERP Variables rows exist
// to prevent.
//
// Carried-forward cases are NOT re-written: they were not re-scored this run, and
// re-inserting them would fabricate a fresh scoring event for a case nobody looked
// at.
const payload = $input.first().json;
const cases = ((payload.result_data || {}).cases) || [];
const runId = String(payload.run_id || '');
const scoredAt = new Date().toISOString();

function numOrOmit(target, key, v) {
  if (v === null || v === undefined || v === '' || !Number.isFinite(Number(v))) return;
  target[key] = Number(v);
}

const out = [];
for (const c of cases) {
  if (c.carried_forward === true) continue;

  const r = {
    run_id: runId,
    case_key: String(c.case_key || ''),
    txn_id: String(c.txn_id || ''),
    txn_date: String(c.txn_date || ''),
    maid_id: String(c.maid_id || ''),
    // The check page's own column list for the workbook includes the maid name, and
    // a data table is the workbook-role target here. It is deliberately NOT put in
    // the run summary or any email. Phone numbers are never carried at all.
    maid_name: String(c.maid_name || ''),
    contract_id: String(c.contract_id || ''),
    reduction_reason: String(c.reduction_reason || ''),
    statuses_seen: String(c.statuses_seen || ''),
    state: String(c.state || ''),
    verdict: String(c.verdict_word || ''),
    reason_code: String(c.reason_code || ''),
    reason_text: String(c.reason_text || ''),
    scored_at: scoredAt,
    days_x50_ok: c.days_x50_ok === true,
    threshold_applies: c.threshold_applies === true,
    sub300_client_paid: c.sub300_client_paid === true,
    payments_complete: c.payments_complete === true
  };

  numOrOmit(r, 'txn_amount', c.txn_amount);
  numOrOmit(r, 'fine_gross', c.fine_gross);
  numOrOmit(r, 'fine_net', c.fine_net);
  numOrOmit(r, 'reduced_amount', c.reduced_amount);
  numOrOmit(r, 'overstay_days', c.overstay_days);
  numOrOmit(r, 'expected_aed', c.expected_aed);
  numOrOmit(r, 'received_aed', c.received_aed);
  numOrOmit(r, 'gap_aed', c.gap_aed);
  numOrOmit(r, 'residue_aed', c.residue_aed);

  out.push({ json: r });
}

if (out.length === 0) {
  // Zero items means the Data table node simply does not run — the correct
  // behaviour for a window with nothing to write, and NOT something to paper over
  // with a synthetic item.
  return [];
}
return out;

// Build Run Row — MV Overstay Fines (v1)
//
// One appended line per run, shaped to the 23 columns of the data table
// "MV Overstay Fines Runs (test)" (id MlL32f9HD8OcgbTp). The Skeleton Contract's
// runs log: "so there is always a record that it ran".
//
// It carries the POPULATION PROOF, not just the outcome — cohort count, pages
// walked and whether the walk reconciled. The Skeleton Contract's population guard
// requires every run to prove its own population, because a complete page walk
// proves the pagination and says nothing about whether the cohort is the right set.
//
// COUNTS AND TOTALS ONLY. No maid, no contract, no per-case amount reaches this
// row: this check handles sensitive data, and the run summary is exactly the place
// the build rules forbid individual figures from reaching.
const payload = $input.first().json;
const s = payload.summary || {};
const intake = (payload.result_data || {}).intake_stats || {};
const validated = $('Validate Inputs').first().json;
const cases = ((payload.result_data || {}).cases) || [];

// The Runs table has a `review` column. These are the cases that landed pending
// because something had to be looked at by a human rather than because money is in
// flight — unattributed, no fine record read, truncated payments, missing fields.
// Keeping them countable separately is the difference between "waiting for the
// client" and "waiting for us".
let review = 0;
for (const c of cases) {
  if (c.carried_forward === true) continue;
  if (c.state === 'pending' && c.escalated === true) review += 1;
}

function n(v) { return Number.isFinite(Number(v)) ? Number(v) : 0; }

return [{
  json: {
    run_id: String(payload.run_id || ''),
    check_id: String(payload.check_id || 'mv-overstay-fines'),
    check_name: 'MV Overstay Fines',
    window_from: String(validated.range_start || ''),
    window_to: String(validated.range_end || ''),
    trigger: String(((validated.params || {}).trigger_source) || 'manual'),
    txns_seen: n(intake.cohort_count),
    txns_pages: n(intake.pages_fetched),
    txns_with_overstay: n(intake.with_overstay),
    cases_scored: n(s.cases_scored),
    red: n(s.red),
    green: n(s.green),
    pending: n(s.pending),
    review: review,
    sub300_collected_count: n(s.sub300_collected_count),
    sub300_collected_aed: n(s.sub300_collected_aed),
    residue_count: n(s.residue_count),
    residue_aed: n(s.residue_aed),
    outstanding_aed: n(s.outstanding_aed),
    // False here is not cosmetic. `Verify Cohort Pull` throws before this node can
    // be reached if the walk did not reconcile, so a false value in this column
    // means something downstream of that assertion changed and the run must not be
    // trusted.
    population_complete: intake.population_complete === true,
    overall: String(s.overall || ''),
    notes: String(payload.run_note || ''),
    completed_at: new Date().toISOString()
  }
}];

// Select Red Cases — MV Overstay Fines (v1)
//
// Every red flag is re-examined. No cap.
//
// The cap the golden used to carry was never really about the model — it was
// standing in for rate limiting that did not exist, back when the evidence nodes
// ran at batchSize -1 / batchInterval 0. Bursts like that are what got this ERP
// account disabled in June 2026. Removing the cap is only safe TOGETHER WITH the
// batching set on the evidence nodes here (batchSize 5, batchInterval 500). If
// anyone resets those to -1/0, restore a cap in the same change.
//
// Skipped: carried-forward cases (not re-scored this run) and any case with no
// maid_id — the complaints endpoint is keyed on the maid, and interpolating an
// empty id into the URL path makes ERP answer 400 on the path segment itself and
// takes the whole run down with it.
//
// The structured waiver NEVER reaches the verifier. gate 9 already settled it, and
// 19 of the 20 findings in the last manual run were waived and visible right on
// that record — handing it to the agent reproduces that false-positive rate.
const payload = $('Build Case Payload').first().json;
const cases = ((payload.result_data || {}).cases) || [];

const out = [];
const skipped = { carried_forward: 0, no_maid_id: 0, not_red: 0, no_verifier_needed: 0 };

for (const c of cases) {
  if (c.carried_forward === true) { skipped.carried_forward += 1; continue; }
  if (c.state !== 'red') { skipped.not_red += 1; continue; }
  if (c.needs_verifier !== true) { skipped.no_verifier_needed += 1; continue; }
  if (!c.maid_id) { skipped.no_maid_id += 1; continue; }

  out.push({
    json: {
      case_key: c.case_key,
      txn_id: c.txn_id,
      txn_date: c.txn_date,
      txn_amount: c.txn_amount,
      maid_id: String(c.maid_id),
      maid_name: c.maid_name || '',
      contract_id: String(c.contract_id || ''),
      fine_gross: c.fine_gross,
      fine_net: c.fine_net,
      overstay_days: c.overstay_days,
      reduced_amount: c.reduced_amount,
      reduction_reason: c.reduction_reason || '',
      expected_aed: c.expected_aed,
      received_aed: c.received_aed,
      in_flight_aed: c.in_flight_aed,
      dead_aed: c.dead_aed,
      gap_aed: c.gap_aed,
      residue_aed: c.residue_aed,
      statuses_seen: c.statuses_seen,
      bill_client: c.bill_client === true,
      client_was_asked: c.client_was_asked === true,
      unexplained: c.unexplained === true,
      verifier_rule: c.verifier_rule || 'not_recovered',
      reason_code: c.reason_code,
      reason_text: c.reason_text,
      check_id: payload.check_id,
      run_id: payload.run_id,
      callback_url: payload.callback_url,
      _skipped: skipped
    }
  });
}

if (out.length === 0) {
  // No reds to verify is a real and common outcome. Zero items means the evidence
  // nodes simply do not run; nothing is synthesised to keep the branch alive.
  return [];
}
return out;

// Split Relevant Complaints — MV Overstay Fines (v1)
//
// One item per complaint whose THREAD is worth fetching, so `Get Complaint Thread`
// makes one call per complaint rather than one per case.
//
// The list response already carries `initialDescription` — the staff member's
// opening statement of why the ticket was opened — at no extra call. That is a
// PRIMARY staff-written source and it is kept in full.
//
// NEVER TREAT THE `summary` FIELD AS EVIDENCE. It is ERP's own auto-generated
// compression, frequently blank, and not what staff wrote. It is dropped here so it
// cannot reach the verifier at all: a check elsewhere in this workspace stamped a
// complaint "NO TEXT" off a blank summary while its initialDescription read
// "client paid the Travel assist fee of AED 9,480 via CC".
//
// The keyword scan below decides only WHICH THREADS TO FETCH. It is a call-budget
// filter, never evidence: a complaint whose type or free text merely contains a
// matching word proves a related ticket EXISTS, not that it EXPLAINS anything.
// Every complaint on the maid is passed through regardless of whether it matched,
// so the verifier still sees the full list and can judge the actual words.
const CASES = $('Select Red Cases').all().map(function (i) { return i.json; });
const PAGES = $input.all().map(function (i) { return i.json; });

// Cheap relevance hints for thread-fetch ordering. Deliberately broad.
const HINT_RE = /overstay|over[- ]stay|os\s*f|osf|fine|waiv|reduc|amer|immigration|change\s*of\s*status|visa\s*delay|noqodi|tasheel|tadbeer/i;
const MAX_THREADS_PER_CASE = 8;

const out = [];

for (let idx = 0; idx < PAGES.length; idx++) {
  const body = PAGES[idx] || {};
  const kase = CASES[idx] || CASES[0] || {};
  const content = Array.isArray(body.content) ? body.content
    : (Array.isArray(body) ? body : []);

  const complaints = content.map(function (c) {
    const primary = c.primaryType || {};
    return {
      complaint_id: c.id === undefined ? '' : String(c.id),
      // PRIMARY staff-written source, already here, no extra call.
      initial_description: String(c.initialDescription || ''),
      primary_type: String(primary.name || primary.label || primary.code || ''),
      status: String((c.status || {}).value || c.status || ''),
      created: String(c.creationDate || c.createdDate || ''),
      // The linkable ticket a human can open and check the verdict against. Every
      // proof source needs a real link, not just an id.
      link: c.id ? 'https://erp.maids.cc/post-sale-services/open-todo/' + String(c.id) : '',
      hint: HINT_RE.test(String(c.initialDescription || '') + ' ' +
        String(primary.name || primary.label || primary.code || ''))
    };
  });

  const ordered = complaints.slice().sort(function (a, b) {
    return (b.hint ? 1 : 0) - (a.hint ? 1 : 0);
  }).slice(0, MAX_THREADS_PER_CASE);

  for (const c of ordered) {
    if (!c.complaint_id) continue;
    out.push({
      json: Object.assign({}, c, {
        case_key: kase.case_key,
        maid_id: kase.maid_id,
        complaints_total: body.totalElements === undefined ? complaints.length : body.totalElements,
        complaints_returned: complaints.length,
        all_complaints: complaints
      })
    });
  }
}

return out;

// Attach Threads to Cases — MV Overstay Fines (v1)
//
// Folds the per-complaint thread responses back into one index keyed by case, so
// `Build Evidence Bundle` sees each case's complaints with their real comment
// threads attached.
//
// GET /complaints/teamComplaintUpdate/historyOfComplaint/{complaintId} is the REAL
// comment thread — what staff actually typed. Together with `initialDescription`
// it is the whole of the evidence this check allows. ERP's own `summary` field is
// never read here.
const threads = $input.all().map(function (i) { return i.json; });
let metas = [];
try {
  metas = $('Split Relevant Complaints').all().map(function (i) { return i.json; });
} catch (e) {
  metas = [];
}

// Every message field ERP has been seen to use for the body text. Read them in
// order and take the first non-empty one — a thread whose text sits under an
// unexpected key must not silently arrive as an empty quote, because "explained
// with no quote behind it" is an assertion, not evidence.
const TEXT_KEYS = ['comment', 'note', 'description', 'text', 'message', 'body', 'updateDescription'];

function messageText(m) {
  if (!m || typeof m !== 'object') return '';
  for (const k of TEXT_KEYS) {
    const v = m[k];
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
}

function messageWho(m) {
  const u = m.createdBy || m.user || m.employee || m.updatedBy || {};
  if (typeof u === 'string') return u;
  return String(u.label || u.name || u.fullName || u.username || '');
}

function messageWhen(m) {
  return String(m.creationDate || m.createdDate || m.date || m.updateDate || '');
}

const byCase = {};

for (let i = 0; i < threads.length; i++) {
  const meta = metas[i] || {};
  const raw = threads[i] || {};
  const caseKey = String(meta.case_key || '');
  if (!caseKey) continue;

  const rows = Array.isArray(raw) ? raw
    : (Array.isArray(raw.content) ? raw.content
      : (Array.isArray(raw.data) ? raw.data : []));

  const messages = rows.map(function (m) {
    return { who: messageWho(m), when: messageWhen(m), text: messageText(m) };
  }).filter(function (m) { return m.text; });

  if (!byCase[caseKey]) {
    byCase[caseKey] = {
      case_key: caseKey,
      maid_id: meta.maid_id || '',
      complaints_total: meta.complaints_total,
      complaints_returned: meta.complaints_returned,
      complaints: []
    };
    // Seed with the full complaint list so the verifier sees every ticket on the
    // maid, including the ones whose thread was not fetched. A missing thread is
    // visible as an empty array, never as "no complaint".
    for (const c of (meta.all_complaints || [])) {
      byCase[caseKey].complaints.push(Object.assign({}, c, { thread: [], thread_fetched: false }));
    }
  }

  const target = byCase[caseKey].complaints.find(function (c) {
    return String(c.complaint_id) === String(meta.complaint_id);
  });
  if (target) {
    target.thread = messages;
    target.thread_fetched = true;
    target.thread_rows_seen = rows.length;
  } else {
    byCase[caseKey].complaints.push({
      complaint_id: meta.complaint_id,
      initial_description: meta.initial_description || '',
      primary_type: meta.primary_type || '',
      status: meta.status || '',
      created: meta.created || '',
      link: meta.link || '',
      thread: messages,
      thread_fetched: true,
      thread_rows_seen: rows.length
    });
  }
}

return [{ json: { by_case: byCase, cases_with_evidence: Object.keys(byCase).length } }];

// Build Evidence Bundle — MV Overstay Fines (v1)
//
// Assembles one bundle per red case and, where the answer is already settled in
// code, sets a `preset_verdict` so the case never reaches the model. `Needs the
// model?` routes on that field.
//
// WHAT THE VERIFIER IS FOR, AND WHAT IT IS NOT FOR. The check page is explicit:
// the waiver is STRUCTURED (reducedAmount / reductionReason) and belongs to the
// deterministic gates, because 19 of the 20 findings in the last manual run were
// waived and visible right on that record. Handing the waiver to the agent would
// reproduce a 19-in-20 false-positive rate. The verifier's job is only the residue:
// a waiver evidenced ONLY in a complaint (rule 13), "client paid AMER directly"
// (rule 14), and "no record we ever asked and no fine on her OS tab" (rule 15).
//
// EVIDENCE IS WHAT PEOPLE WROTE (rule 16): `initialDescription`, the real comment
// thread, and `reductionReason.label`. ERP's own `summary` field is never carried
// into this bundle at all, so the model cannot rest a verdict on it.
const VALID = ['Agent Justified', 'Agent Red Flag - Auditor Review Required', 'Agent Red Flag - Report to PIL'];

const cases = $('Select Red Cases').all().map(function (i) { return i.json; });

// Threads arrive from `Attach Threads to Cases`, keyed by case then complaint.
let threadIndex = {};
try {
  const t = $('Attach Threads to Cases').first();
  threadIndex = (t && t.json && t.json.by_case) || {};
} catch (e) {
  threadIndex = {};
}

function fmtAed(n) {
  if (n === null || n === undefined) return 'n/a';
  return Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const out = [];

for (const c of cases) {
  const bucket = threadIndex[c.case_key] || {};
  const complaints = Array.isArray(bucket.complaints) ? bucket.complaints : [];

  // Pre-computed facts. The model is told the arithmetic rather than asked to do
  // it, so it cannot invent a different expectation than the one the gates used.
  const facts = [
    'Check: MV Overstay Fines (Money in — a finding is money we did NOT recover).',
    'Transaction ' + c.txn_id + ' dated ' + c.txn_date + ' for AED ' + fmtAed(c.txn_amount) +
      ' on expense 1677 (NEW - MV Housemaids - Change of Status Application). Base cost is AED 575.65.',
    'Maid id ' + c.maid_id + ', MV contract ' + c.contract_id + '.',
    c.unexplained
      ? 'THE MAID HAS NO MATCHING FINE ON HER OS-FINES RECORD AT ALL. There is therefore no ' +
        'authoritative fine amount, and nothing may be billed to the client from this state.'
      : ('Gross fine AED ' + fmtAed(c.fine_gross) + ' over ' + c.overstay_days + ' overstay days at ' +
         'AED 50/day. Structured waiver on the OS-fines record: ' +
         (c.reduced_amount ? ('AED ' + fmtAed(c.reduced_amount) + ' reduced, reason "' +
           (c.reduction_reason || 'none recorded') + '"') : 'NONE') +
         '. Net fine (the expected recovery) AED ' + fmtAed(c.fine_net) + '.'),
    c.unexplained ? 'Overstay-fee payments seen on the contract: ' +
        (c.client_was_asked ? 'YES — the client was billed at some point.' : 'NONE — there is no record the client was ever asked.')
      : ('Threshold: a net fine of AED 300 or more is owed by the client IN FULL; below 300 the ' +
         'company absorbs the whole fine. This fine is ' + (c.expected_aed > 0 ? 'AT OR ABOVE' : 'BELOW') +
         ' the threshold, so the expected recovery is AED ' + fmtAed(c.expected_aed) + '.'),
    c.unexplained ? '' :
      ('Recovered: AED ' + fmtAed(c.received_aed) + ' RECEIVED. In flight: AED ' + fmtAed(c.in_flight_aed) +
       '. On dead rows (DELETED etc.): AED ' + fmtAed(c.dead_aed) + '. Statuses seen: ' +
       (c.statuses_seen || 'none') + '. SHORTFALL AED ' + fmtAed(c.gap_aed) + '.'),
    Number(c.residue_aed) > 0
      ? ('We also paid AED ' + fmtAed(c.residue_aed) + ' ABOVE base + gross fine. This is MENTIONED ' +
         'only. It is never a finding and never added to what the client is asked to pay.')
      : '',
    'Deterministic reason recorded by the gates: ' + (c.reason_text || '')
  ].filter(Boolean);

  const evidence = [];
  for (const cm of complaints) {
    evidence.push({
      kind: 'complaint',
      id: cm.complaint_id,
      link: cm.link,
      complaint_type: cm.primary_type,
      status: cm.status,
      created: cm.created,
      // The two PRIMARY staff-written sources. ERP's `summary` is absent by design.
      initial_description: cm.initial_description || '',
      thread: Array.isArray(cm.thread) ? cm.thread : []
    });
  }

  const anyStaffText = evidence.some(function (e) {
    return String(e.initial_description || '').trim().length > 0 ||
      (e.thread || []).some(function (m) { return String(m.text || '').trim().length > 0; });
  });

  let preset = '';
  let whyNoModel = '';

  // Settled in code #1: there is no staff-written text anywhere on this maid. There
  // is nothing for a language model to read, so asking it to read something would
  // produce a judgement resting on nothing.
  if (!anyStaffText) {
    preset = c.unexplained
      ? 'Agent Red Flag - Auditor Review Required'
      : 'Agent Red Flag - Report to PIL';
    whyNoModel = 'No staff-written text exists on this maid — ' + evidence.length +
      ' complaint(s) read, none carrying an initialDescription or a comment. ' +
      (c.unexplained
        ? 'Combined with no fine on her OS-fines tab this is the "no record anywhere" shape: ' +
          'unexplained, for human investigation, and nothing is billed.'
        : 'Nothing written down explains the shortfall, so the money looks genuinely uncollected.');
  }

  // Settled in code #2: rule 15 hard-blocks a billing verdict. There is no
  // authoritative fine amount, so "Report to PIL" — which asserts collectable money
  // — must never be produced from this state, whatever the complaints say.
  const blockPil = c.unexplained === true;

  out.push({
    json: {
      case_key: c.case_key,
      check_id: c.check_id,
      run_id: c.run_id,
      callback_url: c.callback_url,
      maid_id: c.maid_id,
      contract_id: c.contract_id,
      gap_aed: c.gap_aed,
      verifier_rule: c.verifier_rule,
      unexplained: c.unexplained === true,
      block_pil: blockPil,
      preset_verdict: preset,
      why_no_model: whyNoModel,
      valid_verdicts: VALID,
      // `facts` is an OBJECT, not a bare array, because `Merge Agent Verdicts` is
      // cloned verbatim from the golden and reads `b.facts.review_reason`,
      // `b.facts.gap_total`, `b.facts.comments_read` and `b.facts.complaints_seen`
      // off it. Handing it an array would leave every one of those undefined and
      // the verdict rows would silently carry defaults. `ta_refund_total` is a
      // Travel Assist field that has no meaning here; it stays at 0 rather than
      // being edited out of a node that must not be re-generated.
      facts: {
        lines: facts,
        review_reason: c.verifier_rule || 'red_flag',
        gap_total: c.gap_aed === null || c.gap_aed === undefined ? 0 : Number(c.gap_aed),
        ta_refund_total: 0,
        complaints_seen: evidence.length,
        comments_read: evidence.reduce(function (n, e) { return n + (e.thread || []).length; }, 0)
      },
      evidence: evidence,
      prompt: [
        'CASE ' + c.case_key,
        '',
        'PRE-COMPUTED FACTS (trust these; do not recompute any amount):',
        facts.map(function (f) { return '  - ' + f; }).join('\n'),
        '',
        blockPil
          ? 'HARD BLOCK ON THIS CASE: the maid has no fine on her OS-fines record, so there is no ' +
            'authoritative amount to bill. "Agent Red Flag - Report to PIL" is FORBIDDEN here. ' +
            'Choose between Agent Justified (only with a quote that explains it) and ' +
            'Agent Red Flag - Auditor Review Required.'
          : '',
        '',
        'EVIDENCE (' + evidence.length + ' complaint(s) on this maid). Each item carries the staff ' +
        'member\'s own initialDescription and the real comment thread. There is no ERP summary field ' +
        'in this bundle on purpose:',
        JSON.stringify(evidence, null, 1)
      ].filter(Boolean).join('\n')
    }
  });
}

return out;

parameters.inputSchema:
{
  "type": "object",
  "required": ["verdict", "confidence", "explained", "reasoning", "evidence", "route_to"],
  "properties": {
    "verdict": {
      "type": "string",
      "description": "Exactly one of the three allowed verdicts, never paraphrased. 'Agent Red Flag - Report to PIL' is FORBIDDEN when the case is marked unexplained: there is no authoritative fine amount to bill.",
      "enum": [
        "Agent Justified",
        "Agent Red Flag - Auditor Review Required",
        "Agent Red Flag - Report to PIL"
      ]
    },
    "confidence": { "type": "string", "enum": ["high", "medium", "low"] },
    "explained": {
      "type": "boolean",
      "description": "True only when a QUOTED sentence from a complaint accounts for the non-recovery. A keyword match is never enough, and a complaint merely discussing a waiver is not a waiver having been applied."
    },
    "route_to": {
      "type": "string",
      "description": "Who owns the case next. 'visa_team' when the client appears to have paid AMER or immigration directly - that is unresolved until the Visa team answers whether the company paid a fine the client had already settled. 'investigation' when the fine has no record on the maid's OS-fines tab. 'auditor' for everything else. 'none' when the case is justified.",
      "enum": ["none", "auditor", "visa_team", "investigation"]
    },
    "client_paid_amer": {
      "type": "boolean",
      "description": "True when the evidence indicates the client settled the fine directly with AMER, immigration or the government. Never scored as unrecovered and never closed clean."
    },
    "unexplained": {
      "type": "boolean",
      "description": "True when maids.cc paid a fine that has no matching record on the maid's OS-fines tab and there is no record the client was ever asked. Nothing may be billed from this state."
    },
    "reasoning": {
      "type": "string",
      "description": "Why, in the auditor's own terms. Reference the quote you relied on."
    },
    "waiver_quote": {
      "type": "string",
      "description": "The exact sentence a staff member wrote that waives or reduces the fine, copied verbatim. Required whenever explained is true - a label with no text behind it is an assertion, not evidence."
    },
    "evidence": {
      "type": "array",
      "description": "At least one item on any verdict except an empty-evidence Report to PIL. Links are copied from the bundle, never invented.",
      "items": {
        "type": "object",
        "required": ["kind", "link"],
        "properties": {
          "kind": { "type": "string", "description": "complaint | os_fines_record" },
          "id": { "type": "string" },
          "link": { "type": "string", "description": "The real ERP link a human can open, copied from the evidence list." },
          "quote": { "type": "string", "description": "The staff-written sentence this verdict rests on. Never ERP's auto-generated summary field." }
        }
      }
    }
  }
}

parameters.jsCode:
// Merge Agent Verdicts - reconcile the two branches into one verdict per case.
//
// Every case leaves here as exactly one of three `decided_by` values:
//   deterministic - Build Evidence Bundle already settled it (relief covers the
//                   gap, or nothing staff-written exists anywhere). Skipped the
//                   model; carries why_no_model.
//   model         - genuinely ambiguous, judged by the verifier.
//   unreviewed    - routed to the verifier, came back unusable (errored item,
//                   missing item, or no valid verdict). Carries a safe default
//                   verdict and why_no_model, and is counted in `unreviewed`.
//                   NEVER report one of these as a model judgement.
//
// The verifier only ever saw the non-deterministic bundles, in order, so its Nth
// output belongs to the Nth non-deterministic bundle. Walking the bundles and
// advancing a separate cursor is what keeps that pairing correct across the gate.
// The verifier may not have executed at all - hence the try/catch.
//
// VERIFIER_NODE must name the node that actually emits verdicts. It has been
// three different nodes now - the Anthropic agent, then 'Gemini Verdicts' (the
// REST path), and now the 'Verify Red Flags' agent again on a Gemini credential.
// Every time it moved, this constant had to move with it: if it names a node
// that did not run, the read below THROWS, the catch swallows it, agentOuts is
// empty, and every verdict is silently discarded while the run still reports a
// completed review. Change this string whenever the verifier changes.
const VERIFIER_NODE = 'Verify Red Flags';

// The only verdicts that exist. Anything else did not come from a working model,
// whatever the item looks like. Mirrors the enum in the 'Verdict Schema' node -
// if you change one, change the other.
const VALID_VERDICTS = [
  'Agent Justified',
  'Agent Red Flag - Auditor Review Required',
  'Agent Red Flag - Report to PIL'
];
const FALLBACK_VERDICT = 'Agent Red Flag - Auditor Review Required';

const validated = $('Validate Inputs').first().json;
const bundles = $('Build Evidence Bundle').all().map(function (i) { return i.json; });

let agentOuts = [];
try {
  agentOuts = $(VERIFIER_NODE).all().map(function (i) { return i.json; });
} catch (e) {
  agentOuts = [];   // every case was deterministic; the verifier never ran
}

// Derive the agent-review endpoint BEFORE doing any work: if it cannot be
// derived, posting the verdicts anywhere else would misfile them (ta-callback
// would reject them as a duplicate results post, or worse). Throwing here hands
// the failure to the error rail, which emails it. The main results callback has
// already succeeded on this same URL by the time this node runs, so this only
// fires on a genuinely malformed caller.
const cbUrl = String(validated.callback_url || '');
if (cbUrl.indexOf('/ta-callback/') === -1) {
  throw new Error('Cannot derive the agent-review endpoint: callback_url does not contain ' +
    '"/ta-callback/" (got "' + cbUrl.slice(0, 120) + '"). Refusing to post verdicts to a guessed URL.');
}
const reviewUrl = cbUrl.replace('/ta-callback/', '/ta-agent-review/');

const nowIso = new Date().toISOString();
const cases = [];
const tally = {};
let cursor = 0, byModel = 0, byCode = 0, missingModelOutputs = 0;
let modelRouted = 0;                  // bundles SENT to the verifier
const unreviewedKeys = [];            // routed, but came back without a usable verdict
const verifierErrors = [];            // distinct error strings, for the run summary

for (const b of bundles) {
  if (!b || !b.case_key) continue;

  let verdict, confidence, bucket, coversGap, reasoning, evidence, decidedBy, whyNoModel;

  // MV-specific verdict fields. The 'Verdict Schema' node REQUIRES the model to
  // answer five questions this node originally discarded, because it was ported
  // from the Travel Assist golden and never finished the port: explained
  // (verifier rule 1 - a waiver evidenced only in a complaint), client_paid_amer
  // (rule 2), unexplained (rule 3), route_to (who owns the case next) and
  // waiver_quote (the verbatim sentence rule 1 rests on). Read them here or they
  // are gone - nothing downstream can recover a value this node did not copy.
  // route_to is the one that makes a verdict actionable at all: 'visa_team' and
  // 'investigation' are different desks, and they ARE rules 2 and 3.
  let explained = false, unexplained = false, clientPaidAmer = false;
  let routeTo = 'auditor', waiverQuote = '';

  // Payment follow-up (from the client message log). The code-derived answer is
  // the floor: deterministic and unreviewed cases use it as-is; a model case may
  // override it with a validated enum value plus its own quoted evidence.
  const FOLLOWUP_VALUES = ['yes', 'no', 'unclear'];
  let paymentFollowup = (b.facts && FOLLOWUP_VALUES.indexOf(b.facts.sms_payment_followup) !== -1)
    ? b.facts.sms_payment_followup : 'unclear';
  let paymentFollowupEvidence = (b.facts && b.facts.sms_payment_followup_note) || '';

  if (b.preset_verdict) {
    decidedBy  = 'deterministic';
    whyNoModel = b.why_no_model || null;
    verdict    = b.preset_verdict;
    confidence = 'high';           // arithmetic or a proven absence, not a judgement
    bucket     = (b.facts && (b.facts.flagged_buckets || []).join(', ')) || '';
    coversGap  = !!(b.facts && b.facts.discount_covers_gap);
    reasoning  = whyNoModel || 'Decided in code without the model.';
    evidence   = Array.isArray(b.evidence) ? b.evidence : [];
    // Code decided it, so the model answered nothing. These carry what the
    // deterministic gates already knew and are never guessed from the verdict.
    unexplained = !!(b.facts && b.facts.unexplained === true);
    routeTo     = (b.preset_verdict === 'Agent Justified') ? 'none' : 'auditor';
    byCode++;
  } else {
    modelRouted++;
    const raw = agentOuts[cursor++];

    // JUDGE THE PAYLOAD, NOT THE SLOT. The verifier runs with
    // onError: continueRegularOutput, which emits one item per input item even
    // when the model call died - a failure arrives as a PRESENT item carrying
    // {error: "..."}, never as a gap. So testing `!raw` alone only catches a
    // SHORT array, which is the rarer failure.
    //   Execution 77248 (2026-08-06): Gemini's free-tier quota (20 req/min,
    //   shared project) killed 4 of 7 items. All 7 arrived, 4 of them as
    //   {"error":"The service is receiving too many requests from you"}. The old
    //   `!raw` test passed them straight through: decided_by:'model',
    //   reasoning:'', evidence back-filled from the bundle, while
    //   missing_model_outputs stayed 0 and pairing_ok stayed true. Four
    //   unreviewed cases were indistinguishable from three real verdicts.
    const v = (raw && (raw.output || raw)) || {};
    const itemErr = (raw && raw.error != null)
      ? String((raw.error && raw.error.message) || raw.error).slice(0, 300)
      : '';
    const verdictIn = typeof v.verdict === 'string' ? v.verdict.trim() : '';
    const verdictOk = VALID_VERDICTS.indexOf(verdictIn) !== -1;

    if (!raw || itemErr || !verdictOk) {
      // Not reviewed. Say so on the case, in the counters, and in the reasoning
      // a human will actually read.
      missingModelOutputs++;
      unreviewedKeys.push(b.case_key);
      if (itemErr && verifierErrors.indexOf(itemErr) === -1) verifierErrors.push(itemErr);

      whyNoModel = itemErr
        ? 'verifier errored on this case: ' + itemErr
        : (!raw
            ? 'no model output arrived (expected item ' + cursor + ' of ' +
              agentOuts.length + ' received)'
            : 'model returned an item with no valid verdict (got "' +
              (verdictIn || typeof v.verdict) + '")');

      decidedBy  = 'unreviewed';
      verdict    = FALLBACK_VERDICT;   // fails CLOSED - a human still has to look
      confidence = 'none';
      bucket     = (b.facts && (b.facts.flagged_buckets || []).join(', ')) || '';
      coversGap  = false;
      reasoning  = 'NOT REVIEWED - ' + whyNoModel + '. No model judgement was made on ' +
                   'this case; the verdict is a safe default, not a finding. Re-run the ' +
                   'verifier for this case before treating it as reviewed.';
      evidence   = Array.isArray(b.evidence) ? b.evidence : [];
      unexplained = !!(b.facts && b.facts.unexplained === true);
      routeTo     = 'auditor';   // nobody judged it; a human still has to
    } else {
      decidedBy  = 'model';
      whyNoModel = null;
      verdict    = verdictIn;
      confidence = String(v.confidence || 'low');
      bucket     = String(v.bucket || '');
      coversGap  = v.covers_gap === true;
      reasoning  = String(v.reasoning || '');
      // Model's follow-up answer wins when it is a valid enum value; anything
      // else keeps the code-derived floor rather than inventing a fourth state.
      if (FOLLOWUP_VALUES.indexOf(v.payment_followup) !== -1) {
        paymentFollowup = v.payment_followup;
        if (typeof v.payment_followup_evidence === 'string' && v.payment_followup_evidence.trim()) {
          paymentFollowupEvidence = v.payment_followup_evidence.trim();
        }
      }
      // Prefer the model's cited evidence; fall back to what we handed it so a row
      // is never left with no link at all.
      evidence   = (Array.isArray(v.evidence) && v.evidence.length)
                   ? v.evidence
                   : (Array.isArray(b.evidence) ? b.evidence : []);
      explained      = v.explained === true;
      unexplained    = v.unexplained === true;
      clientPaidAmer = v.client_paid_amer === true;
      waiverQuote    = typeof v.waiver_quote === 'string' ? v.waiver_quote : '';
      // Validate against the schema's own enum rather than trusting the string:
      // an unrecognised route silently misfiles a case to a desk that does not
      // exist, which reads exactly like a case nobody routed.
      const ROUTES = ['none', 'auditor', 'visa_team', 'investigation'];
      routeTo = ROUTES.indexOf(v.route_to) !== -1 ? v.route_to : 'auditor';
      byModel++;
    }
  }

  tally[verdict] = (tally[verdict] || 0) + 1;

  cases.push({
    case_key: b.case_key,
    agent_review: {
      verdict: verdict,
      confidence: confidence,
      bucket: bucket,
      covers_gap: coversGap,
      reasoning: reasoning,
      evidence: evidence,
      decided_by: decidedBy,
      why_no_model: whyNoModel,
      payment_followup: paymentFollowup,
      payment_followup_evidence: paymentFollowupEvidence,
      review_reason: (b.facts && b.facts.review_reason) || 'red_flag',
      explained: explained,
      unexplained: unexplained,
      client_paid_amer: clientPaidAmer,
      route_to: routeTo,
      waiver_quote: waiverQuote,
      ta_refund_total: (b.facts && b.facts.ta_refund_total) || 0,
      gap_total: (b.facts && b.facts.gap_total) || 0,
      comments_read: (b.facts && b.facts.comments_read) || 0,
      complaints_seen: (b.facts && b.facts.complaints_seen) || 0,
      reviewed_at: nowIso
    }
  });
}

// Pairing integrity: the model path is positional, so the only acceptable
// relationship is exactly one verifier output per bundle ROUTED to the verifier.
// This must compare against modelRouted, not byModel - byModel now counts only
// the items that came back usable, so comparing to it would report pairing_ok
// false on every quota-degraded run and hide the real pairing question.
const pairingOk = agentOuts.length === modelRouted;

// A run where the model answered nothing it was asked is not a review. Callers
// should treat this as "verifier unavailable", not as a set of verdicts.
const verifierDown = modelRouted > 0 && byModel === 0;

console.log(JSON.stringify({ stage: 'merge_agent_verdicts', reviewed: cases.length,
  by_model: byModel, by_code: byCode, model_routed: modelRouted,
  model_outputs_seen: agentOuts.length, unreviewed: missingModelOutputs,
  pairing_ok: pairingOk, verifier_down: verifierDown,
  verifier_errors: verifierErrors, tally: tally }));

return [{ json: {
  check_id: validated.check_id,
  run_id: validated.run_id,
  callback_url: reviewUrl,
  reviewed: cases.length,
  decided_by_model: byModel,
  decided_in_code: byCode,
  // Routed to the verifier but not actually judged by it. `missing_model_outputs`
  // keeps its old name for the existing callback contract, but its meaning is now
  // "no USABLE verdict" rather than only "no item at all".
  unreviewed: missingModelOutputs,
  missing_model_outputs: missingModelOutputs,
  unreviewed_case_keys: unreviewedKeys,
  verifier_errors: verifierErrors,
  verifier_down: verifierDown,
  model_routed: modelRouted,
  pairing_ok: pairingOk,
  tally: tally,
  cases: cases,
  completed_at: nowIso
}}];

// Format Agent Review Email - what the auditor must act on, after the verifier.
//
// WHY IT SITS HERE, NOT AT THE END OF THE RUN. The two lists this email exists
// to deliver - "report to PIL" and "auditor review required" - are VERDICTS, and
// verdicts do not exist when the audit finishes. The results callback fires in
// Band 4; the verifier runs afterwards in Band 5. An email sent "when the run is
// done" would be empty every single time. So this node is chained AFTER
// `Callback: Agent Review`, which means:
//   1. every verdict for the run is known, and
//   2. the verdicts are already safely posted - a mail failure can never cost
//      them, because the callback has already returned by the time we run.
//
// No URL/fetch/require: the n8n Code sandbox has none of them (see NODES.md).

const merged = $('Merge Agent Verdicts').first().json;
const cases  = Array.isArray(merged.cases) ? merged.cases : [];

// Names and money live on the verifier's intake, not on the verdict itself.
const nameByKey = {};
try {
  for (const it of $('Select Red Cases').all()) {
    const j = it.json || {};
    if (j.case_key) nameByKey[String(j.case_key)] = j;
  }
} catch (e) {
  // Intake unreachable (shape change, node rename): the email still goes out,
  // just without names. Losing a decoration must never lose the alert.
}

let auditWindow = '';
try {
  const w = $('Build Case Payload').first().json.result_data.summary.audit_window || {};
  if (w.from && w.to) auditWindow = w.from + ' to ' + w.to;
} catch (e) { /* subject degrades to no window */ }

const PIL      = 'Agent Red Flag - Report to PIL';
const AUDITOR  = 'Agent Red Flag - Auditor Review Required';
const JUSTIFIED = 'Agent Justified';

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
function aed(n) {
  const v = Number(n) || 0;
  return 'AED ' + Math.round(v).toLocaleString('en-US');
}

const toPil = [];
const toReview = [];
const notReviewed = [];
let justified = 0;

for (const c of cases) {
  const r = c.agent_review || {};
  // An 'unreviewed' case carries a PLACEHOLDER verdict (Auditor Review) purely so
  // nothing escapes attention. It is NOT a judgement and must be listed apart, or
  // the auditor cannot tell "the model looked and said review" from "the model
  // never answered".
  if (String(r.decided_by || '').toLowerCase() === 'unreviewed') { notReviewed.push(c); continue; }
  if (r.verdict === PIL) { toPil.push(c); continue; }
  if (r.verdict === AUDITOR) { toReview.push(c); continue; }
  if (r.verdict === JUSTIFIED) { justified++; }
}

function sortByGap(a, b) {
  return (Number((b.agent_review || {}).gap_total) || 0) - (Number((a.agent_review || {}).gap_total) || 0);
}
toPil.sort(sortByGap); toReview.sort(sortByGap); notReviewed.sort(sortByGap);

const CASES_LINK = 'https://security-room.lovable.app/checks/' +
  encodeURIComponent(merged.check_id || '') + '?tab=cases&cases=red';

function table(rows, emptyLine) {
  if (!rows.length) {
    return '<p style="margin:6px 0 18px;color:#666;font-size:13px;">' + esc(emptyLine) + '</p>';
  }
  let h = '<table cellpadding="6" cellspacing="0" border="0" ' +
    'style="border-collapse:collapse;width:100%;font-size:13px;margin:6px 0 18px;">' +
    '<tr style="background:#f4f4f4;">' +
    '<th align="left" style="border-bottom:1px solid #ddd;">Contract</th>' +
    '<th align="left" style="border-bottom:1px solid #ddd;">Maid</th>' +
    '<th align="right" style="border-bottom:1px solid #ddd;">Gap</th>' +
    '<th align="left" style="border-bottom:1px solid #ddd;">Why</th></tr>';
  for (const c of rows) {
    const r = c.agent_review || {};
    const meta = nameByKey[String(c.case_key)] || {};
    // Maid only. The client name was inherited from the Travel Assist golden and
    // nothing in this check ever resolves it - clientId is an empty string on
    // every transaction row and the client is only reachable through the
    // contract, which this flow does not walk. The column rendered '-> -' on
    // every row, which reads as a lookup that failed rather than a field that was
    // never fetched. ERP names are free text, so it is still escaped.
    const who = esc(meta.maid_name || '-');
    let why = String(r.reasoning || '').trim();
    if (why.length > 240) why = why.slice(0, 240) + '...';
    // Route, not payment-follow-up. `payment_followup` is a Travel Assist field:
    // its only source was `facts.sms_payment_followup`, which nothing in this
    // flow produces, so the badge printed 'Payment follow-up unclear' on every
    // row forever - a permanent warning about a question nobody asked.
    // `route_to` is real, comes off the verdict schema, and says which desk owns
    // the case: rule 2 (client paid AMER) and rule 3 (no OS-fines record).
    const route = String(r.route_to || '');
    const followNote = route === 'visa_team'
      ? '<div style="color:#0057b8;margin-top:3px;">Route: Visa team - client appears to have paid AMER directly</div>'
      : (route === 'investigation'
          ? '<div style="color:#a00;margin-top:3px;">Route: investigation - no record on her OS-fines tab, nothing may be billed</div>'
          : '');
    h += '<tr>' +
      '<td style="border-bottom:1px solid #eee;font-family:monospace;">' + esc(c.case_key) + '</td>' +
      '<td style="border-bottom:1px solid #eee;">' + who + '</td>' +
      '<td style="border-bottom:1px solid #eee;" align="right">' + esc(aed(r.gap_total)) + '</td>' +
      '<td style="border-bottom:1px solid #eee;">' + esc(why) + followNote + '</td>' +
      '</tr>';
  }
  return h + '</table>';
}

const subject = 'MV Overstay Fines' + (auditWindow ? ' (' + auditWindow + ')' : '') +
  ' - ' + toPil.length + ' to report to PIL, ' + toReview.length + ' to review';

// Every group is stated even when empty. A quiet month and a broken email must
// never look the same in the inbox.
let html =
  '<div style="font-family:Calibri,Arial,sans-serif;max-width:760px;color:#222;">' +
  '<h2 style="margin:0 0 4px;">MV Overstay Fines - cases needing you</h2>' +
  '<p style="margin:0 0 16px;color:#666;font-size:13px;">' +
  'Audit window ' + esc(auditWindow || 'not recorded') + '. ' +
  esc(cases.length) + ' case(s) went through the AI verifier.' +
  '</p>' +

  '<h3 style="margin:18px 0 2px;color:#a00;">Report to PIL (' + toPil.length + ')</h3>' +
  '<p style="margin:0;color:#666;font-size:12px;">Nothing written anywhere explains the shortfall.</p>' +
  table(toPil, 'None this run.') +

  '<h3 style="margin:18px 0 2px;color:#b26a00;">Auditor review required (' + toReview.length + ')</h3>' +
  '<p style="margin:0;color:#666;font-size:12px;">There is something to read before deciding.</p>' +
  table(toReview, 'None this run.');

// Only shown when it happened - an always-present "0 not reviewed" trains the
// eye to skip the row that matters most on the day it is not zero.
if (notReviewed.length) {
  html +=
    '<h3 style="margin:18px 0 2px;color:#666;">Not reviewed by the verifier (' + notReviewed.length + ')</h3>' +
    '<p style="margin:0;color:#666;font-size:12px;">The model was asked and gave no usable answer. ' +
    'These carry a placeholder verdict, not a judgement, and still need a human.</p>' +
    table(notReviewed, 'None this run.');
}

if (merged.verifier_down) {
  html += '<p style="margin:16px 0;padding:10px;background:#fff4f4;border:1px solid #f0c0c0;font-size:13px;">' +
    '<strong>The verifier answered nothing it was asked this run.</strong> Treat the lists above as incomplete.</p>';
}

html +=
  '<p style="margin:18px 0 6px;font-size:13px;">' +
  esc(justified) + ' case(s) the AI justified are not listed - they are green and need nothing from you.' +
  '</p>' +
  '<p style="margin:14px 0;"><a href="' + CASES_LINK + '" ' +
  'style="background:#f60;color:#fff;padding:8px 14px;text-decoration:none;border-radius:4px;font-size:13px;">' +
  'Open the cases in Security Room</a></p>' +
  '<p style="margin:14px 0 0;color:#888;font-size:11px;">' +
  'Sent after the AI verifier finished, which is why it arrives a little after the run itself. Run ' +
  esc(String(merged.run_id || '').slice(0, 8)) + '.</p>' +
  '</div>';

console.log(JSON.stringify({
  stage: 'format_agent_review_email',
  to_pil: toPil.length, to_review: toReview.length,
  not_reviewed: notReviewed.length, justified: justified,
  verifier_down: !!merged.verifier_down
}));

return [{ json: { subject: subject, html: html,
  to_pil: toPil.length, to_review: toReview.length, not_reviewed: notReviewed.length } }];

// Format Failure Email - normalises TWO very different failure shapes into one
// readable email.
//
// Shape A - handled: the error rail's payload from Build Error Callback,
//   { result:'error', error:{ code, message, status, retryable }, run_id, ... }
//
// Shape B - crash: n8n's Error Trigger payload,
//   { execution:{ id, url, error:{ message, stack }, lastNodeExecuted }, workflow:{ id, name } }
//
// Both matter and they catch different things. The rail only sees an ERP call that
// routed to its error output. A THROW - Verify Bulk Pulls in execution 76796 -
// aborts the run and never touches the rail. Without the crash trigger, the loudest
// failures were the silent ones.

const j = $input.first().json || {};
const isCrash = !!(j.execution || j.workflow);

let runId, nodeName, code, message, status, retryable, execId, execUrl, wfName;

if (isCrash) {
  const ex = j.execution || {};
  const wf = j.workflow || {};
  execId   = ex.id || '';
  execUrl  = ex.url || '';
  wfName   = wf.name || 'MV Overstay Fines Audit';
  nodeName = ex.lastNodeExecuted || '(unknown node)';
  message  = (ex.error && (ex.error.message || ex.error.description)) || 'no message';
  code     = 'workflow_crash';
  status   = null;
  retryable = false;
  try { runId = $('Validate Inputs').first().json.run_id; } catch (e) { runId = '(unknown)'; }
} else {
  const e = j.error || {};
  runId    = j.run_id || '(unknown)';
  nodeName = '(handled - see error rail)';
  code     = e.code || 'internal';
  message  = e.message || 'no message';
  status   = e.status != null ? e.status : null;
  retryable = e.retryable === true;
  wfName   = 'MV Overstay Fines Audit';
  execId = ''; execUrl = '';
}

// What to check first, by failure type. A 498 is overwhelmingly the likely one
// right now: eleven nodes still need their credential attached by hand.
let advice;
if (code === 'erp_auth_expired' || status === 498 || status === 401 || status === 403) {
  advice = 'ERP rejected the credential. Check that every ERP node in the workflow has the ' +
           '"ERP Hassan Prod" credential selected, and that the credential itself is still valid. ' +
           'A 498 means the token is missing or malformed - retrying will not help.';
} else if (code === 'timeout') {
  advice = 'ERP did not respond in time. The nodes allow 90s. If this recurs, ERP is slow ' +
           'under load - consider capping concurrency (batchSize) rather than raising the timeout.';
} else if (code === 'erp_unavailable') {
  advice = 'ERP returned a 5xx. Usually transient - this one IS retryable.';
} else if (code === 'workflow_crash') {
  advice = 'A node threw rather than routing to the error rail. If it was "Verify Bulk Pulls" ' +
           'or "Split Transactions", that is a GUARD firing on purpose: an ERP pull returned no ' +
           'usable data and the run was stopped so it could not report a successful audit of ' +
           'zero cases. Read the message above - it names which pull failed.';
} else {
  advice = 'Open the execution in n8n and read the failing node\'s input and output.';
}

const subject = '[MV Overstay Fines Audit] FAILED - ' + code +
                (status ? ' (HTTP ' + status + ')' : '') +
                ' - run ' + String(runId).slice(0, 8);

function esc(t) {
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const rows = [
  ['What broke', isCrash ? ('a node threw: ' + nodeName) : 'an ERP call failed (handled)'],
  ['Error code', code],
  ['ERP status', status != null ? String(status) : '-'],
  ['Message', message],
  ['Retryable', retryable ? 'yes' : 'no'],
  ['Run id', runId],
  ['Execution', execId ? (execUrl ? ('<a href="' + esc(execUrl) + '">' + esc(execId) + '</a>') : esc(execId)) : '-']
];

const html =
  '<div style="font-family:Calibri,Arial,sans-serif;max-width:640px;">' +
  '<div style="background:#DC2626;color:#fff;padding:12px 16px;font-size:16px;font-weight:bold;">' +
  'MV Overstay Fines Audit - run failed</div>' +
  '<div style="padding:12px 16px;">' +
  '<table style="width:100%;border-collapse:collapse;font-size:13px;">' +
  rows.map(function (r) {
    return '<tr>' +
      '<td style="padding:5px 8px;border-bottom:1px solid #E2E8F0;color:#64748B;width:120px;">' + esc(r[0]) + '</td>' +
      '<td style="padding:5px 8px;border-bottom:1px solid #E2E8F0;">' + (r[0] === 'Execution' ? r[1] : esc(r[1])) + '</td>' +
      '</tr>';
  }).join('') +
  '</table>' +
  '<div style="background:#FEF3C7;border-left:4px solid #B45309;padding:10px 12px;margin-top:14px;font-size:12.5px;">' +
  '<strong>What to check first.</strong><br>' + esc(advice) + '</div>' +
  '<div style="margin-top:12px;font-size:11px;color:#94A3B8;">No audit result was written for this run. ' +
  'Security Room will show it as failed rather than passing with an empty cohort.</div>' +
  '</div></div>';

return [{ json: { subject: subject, html: html, failure_code: code,
                  run_id: runId, execution_id: execId } }];

// Build Verdict Rows - MV Overstay Fines (v1)
//
// WHY THIS NODE EXISTS. The verifier had no durable target. Everything after
// `Merge Agent Verdicts` hung off `Agent Callback Declared?`, which tests
// delivery.portal === true - and `Build Manual Run Context` declares
// portal:false, data_tables:true. On the only trigger this check has, the whole
// post-verifier band no-opped and every verdict died with the execution record.
// Meanwhile `Write Cases (data table)` runs a band EARLIER, so the Cases table's
// `verdict` column holds the PRE-verifier deterministic word and nothing ever
// corrects it: a case the model justifies stays red in the only durable artefact.
//
// This node is the data_tables target the delivery declaration already promised.
// It is wired FIRST off `Merge Agent Verdicts`, ahead of the callback branch, so
// a portal that is off, unreachable or misconfigured can never cost the verdicts.
//
// APPEND-ONLY, BY DESIGN. Cases stays the deterministic snapshot; Verdicts is the
// AI layer; they join on case_key. Keeping them apart is what makes the
// code-vs-model overturn rate visible, and on this check that number matters more
// than usual - 19 of 20 findings in the last manual run were waivers.
const merged = $input.first().json;
const cases  = Array.isArray(merged.cases) ? merged.cases : [];
const runId  = String(merged.run_id || '');

// Identity is not on the verdict. Merge emits case_key and the review, nothing
// else, so txn/maid/contract come from the node that fed the verifier.
const metaByKey = {};
try {
  for (const it of $('Select Red Cases').all()) {
    const j = it.json || {};
    if (j.case_key) metaByKey[String(j.case_key)] = j;
  }
} catch (e) {
  // Intake unreachable (rename, shape change). The verdict is still worth
  // keeping without its ids - losing identity must never lose the judgement.
}

function clip(s, n) {
  const v = String(s == null ? '' : s);
  return v.length > n ? v.slice(0, n) + '...' : v;
}

const out = [];
for (const c of cases) {
  if (!c || !c.case_key) continue;
  const r  = c.agent_review || {};
  const m  = metaByKey[String(c.case_key)] || {};
  const ev = Array.isArray(r.evidence) ? r.evidence : [];

  out.push({ json: {
    run_id:      runId,
    case_key:    String(c.case_key),
    txn_id:      String(m.txn_id || ''),
    maid_id:     String(m.maid_id || ''),
    contract_id: String(m.contract_id || ''),

    verdict:       String(r.verdict || ''),
    // 'unreviewed' carries a PLACEHOLDER verdict so nothing escapes attention. It
    // is not a judgement, and a reader of this table must be able to tell the two
    // apart without opening the execution - hence decided_by beside every verdict.
    decided_by:    String(r.decided_by || ''),
    confidence:    String(r.confidence || ''),
    review_reason: String(r.review_reason || ''),
    why_no_model:  String(r.why_no_model || ''),

    // The desk that owns the case next. visa_team = verifier rule 2 (client
    // appears to have paid AMER directly), investigation = rule 3 (no record on
    // her OS-fines tab, so nothing may be billed from that state).
    route_to:         String(r.route_to || ''),
    client_paid_amer: r.client_paid_amer === true,
    unexplained:      r.unexplained === true,

    // waiver_seen is the verifier's `explained`: true ONLY when a quoted
    // staff-written sentence accounts for the non-recovery. The quote is stored
    // beside it rather than folded into the reasoning - a quote a human can go
    // and check is the evidence; the reasoning is only the argument built on it,
    // and a label with no text behind it is an assertion.
    waiver_seen:  r.explained === true,
    waiver_quote: clip(r.waiver_quote, 4000),

    reasoning:       clip(r.reasoning, 4000),
    evidence:        clip(JSON.stringify(ev), 8000),
    evidence_links:  clip(ev.map(function (e) { return String((e && e.link) || ''); })
                            .filter(Boolean).join(' | '), 2000),
    complaints_seen: Number(r.complaints_seen) || 0,
    comments_read:   Number(r.comments_read) || 0,

    // Not per-case: true means the model answered NOTHING it was asked this run,
    // so every row of this run is suspect. Stamped on each row so a query that
    // reads a single case still sees it.
    verifier_down: merged.verifier_down === true,
    reviewed_at:   String(r.reviewed_at || new Date().toISOString())
  }});
}

console.log(JSON.stringify({ stage: 'build_verdict_rows', rows: out.length,
  run_id: runId, verifier_down: merged.verifier_down === true }));

// Zero rows means the Data table node simply does not run - the correct outcome
// for a run with no reds, and not something to paper over with a synthetic item.
return out;

// ERP PRE-FLIGHT BUDGET GATE — ERP-LOAD-POLICY.md §3. Canonical: tools/erp_preflight_gate.js.
//
// Sits between `Route by skip_computation` and `Attach Identity`, which is still the last point
// before the first PER-ENTITY ERP call - identity itself no longer costs one, so the first such
// call is now `Get Overstay Fines`. Everything upstream is the paginated cohort sweep, whose
// cost is a handful of pages; everything downstream multiplies by the population.
//
// It is deliberately AFTER the switch rather than before it, so it counts the items that will
// actually be enriched (`in_range`) and not the carried-forward cases, which cost nothing: a
// gate that over-counts is a gate someone eventually raises the budget to silence.
//
// WHY VOLUME NEEDS ITS OWN CONTROL. Pacing bounds requests per second; it does not bound how
// many there are. This flow paced perfectly at 4 req/s still makes 11N calls for N over-base
// transactions, and that is the shape of the failure that took ERP down three times: a check
// tested on August (151 cohort rows) behaves identically on January (811), and nothing in
// between makes the cost visible before the calls go out.
//
// IT HARD-FAILS. It does not trim the cohort to fit. Auto-capping produces a run that completes
// with incomplete coverage, and a partial audit that looks complete is the single failure this
// whole check family exists to avoid - the same reason `Verify Cohort Pull` aborts on a short
// walk instead of scoring what it got.

// --- per-flow constants: what this run actually costs, stated honestly -----------------------
// ENRICHMENT LANE, one call each per over-base transaction:
//   1. Get Overstay Fines       - only for identity-RESOLVED transactions, so fewer in practice.
//   2. Get Overstay Payments    - same subset.
// Budgeted at the full count rather than the resolved subset, because a budget that assumes the
// happy case is not a budget.
//
// 2026-08-30: WAS 3. `Get Transaction Detail` - one call per transaction purely to learn which
// maid the transaction belonged to - is gone. The cohort route moved to the legacy
// /accounting/transactions/page/advancesearch, which projects housemaids[] with the population,
// so identity now costs ZERO per-entity calls. A real reduction, not a re-estimate.
const ERP_CALLS_PER_TRANSACTION = 2;

// EVIDENCE LANE, downstream of `Build Case Payload`, per RED case:
//   3. Get Maid Complaints      - one list call.
//   4. Get Complaint Thread     - up to MAX_THREADS_PER_CASE = 8, the cap set in
//                                 `Split Relevant Complaints`.
// Only red cases reach it, and a normal month reds a small minority - but "how many will be red"
// is exactly what this run has not computed yet, so the worst case is one red per transaction.
// This is the larger half of the bill and the half a reader is most likely to forget: the
// enrichment sticky note has always talked about the per-transaction calls alone, and those are
// now TWO of the eleven.
const ERP_CALLS_DOWNSTREAM_PER_TRANSACTION = 9;

const ERP_CALLS_PER_ENTITY = ERP_CALLS_PER_TRANSACTION + ERP_CALLS_DOWNSTREAM_PER_TRANSACTION; // 11

// Cohort pages already spent. January (811 rows) walks 5 pages at size=200; the node's own
// maxRequests hard-caps the walk at 50. Only used when the run cannot report what it walked.
const SWEEP_CALLS_FALLBACK = 5;

const DEFAULT_BUDGET = 2000;         // ERP-LOAD-POLICY.md §1 — a run that names no budget
const SIGNOFF_THRESHOLD = 15000;     // above this a human decision must be recorded first

const _validated = $('Validate Inputs').first().json || {};
const params = _validated.params || {};

const askedBudget = Number(params.erp_call_budget);
const budget = Number.isFinite(askedBudget) && askedBudget > 0 ? askedBudget : DEFAULT_BUDGET;

// Prefer what the run MEASURED over the constant: `Verify Cohort Pull` already reconciled the
// walk and knows how many pages it took, and a real number beats an estimate that quietly ages.
let measuredPages = 0;
try { measuredPages = Number($('Verify Cohort Pull').first().json.pages_fetched) || 0; } catch (e) { measuredPages = 0; }
if (!measuredPages) {
  try { measuredPages = $('Get Change of Status Transactions').all().length; } catch (e) { measuredPages = 0; }
}
const sweepCalls = measuredPages > 0 ? measuredPages : SWEEP_CALLS_FALLBACK;

// One item per in-range case. `Split Transactions` emits a lone `_no_overstay_in_window` marker
// for a month where nothing cleared the base, and `Merge with previous_cases` drops anything
// without a txn_id, so both are filtered rather than counted as work.
const rows = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && !r._no_overstay_in_window && r.txn_id; });
const entities = rows.length;
const projectedEnrichment = entities * ERP_CALLS_PER_TRANSACTION;
const projectedEvidence = entities * ERP_CALLS_DOWNSTREAM_PER_TRANSACTION;
const projectedTotal = sweepCalls + projectedEnrichment + projectedEvidence;

console.log(JSON.stringify({ stage: 'erp_preflight_gate',
  check: 'mv-overstay-fines',
  run_id: _validated.run_id || null,
  audit_window: String(_validated.range_start || '') + ' to ' + String(_validated.range_end || ''),
  transactions: entities, calls_per_transaction: ERP_CALLS_PER_ENTITY,
  projected_enrichment: projectedEnrichment, projected_evidence_worst_case: projectedEvidence,
  sweep_calls_spent: sweepCalls, projected_total: projectedTotal, budget: budget,
  budget_source: Number.isFinite(askedBudget) && askedBudget > 0
    ? 'params.erp_call_budget' : 'default (' + DEFAULT_BUDGET + ')',
  minutes_at_policy_rate: Math.round(projectedTotal / 4 / 60),
  within_budget: projectedTotal <= budget }));

// ABOVE THE SIGN-OFF THRESHOLD, BE LOUD EVEN WHEN ALLOWED. ERP-LOAD-POLICY.md §7 says a run over
// the threshold needs a recorded human decision. Setting params.erp_call_budget high enough IS
// that decision - it is an explicit act in the payload - but a decision nobody can find later is
// not much of a record. Without this the threshold only ever appeared inside a refusal, which
// meant the one case it most needed to mark - a large run that was ALLOWED - was the case it
// said nothing about.
if (projectedTotal > SIGNOFF_THRESHOLD) {
  console.log(JSON.stringify({ stage: 'erp_preflight_high_volume',
    projected_total: projectedTotal, threshold: SIGNOFF_THRESHOLD, budget: budget,
    minutes_at_policy_rate: Math.round(projectedTotal / 4 / 60),
    allowed: projectedTotal <= budget,
    note: 'ERP-LOAD-POLICY.md §7: a run this size needs a recorded human decision. The explicit ' +
          'params.erp_call_budget is that record; this line is where it can be found afterwards.' }));
}

if (projectedTotal > budget) {
  throw new Error(
    'ERP PRE-FLIGHT GATE: this run would make about ' + projectedTotal + ' ERP calls against a ' +
    'budget of ' + budget + '. Refusing to start the per-entity phase.\n' +
    '  ' + entities + ' over-base transactions x ' + ERP_CALLS_PER_TRANSACTION +
    ' (OS fines + overstay-fee payments; identity rides on the cohort) = ' + projectedEnrichment + '\n' +
    '  ' + entities + ' x ' + ERP_CALLS_DOWNSTREAM_PER_TRANSACTION +
    ' (complaints list + up to 8 threads, worst case every case red) = ' + projectedEvidence + '\n' +
    '  cohort pages already spent = ' + sweepCalls + '\n' +
    '  at the 4 req/s policy rate that is roughly ' + Math.round(projectedTotal / 4 / 60) +
    ' minutes of ERP time.\n' +
    'Two ways forward, and both are deliberate: narrow audit_window so the run is a declared ' +
    'partial, or raise params.erp_call_budget because a full month is genuinely wanted. The ' +
    'cohort is NOT trimmed automatically - a run that quietly audits part of the month and ' +
    'reports like a whole one is the failure this check exists to prevent, and `Verify Cohort ' +
    'Pull` already refuses a partial walk for the same reason.' +
    (projectedTotal > SIGNOFF_THRESHOLD
      ? '\nNOTE: above ' + SIGNOFF_THRESHOLD + ' calls, ERP-LOAD-POLICY.md §7 requires a recorded ' +
        'human decision before the run fires, not just a bigger number in the payload.'
      : ''));
}

// Pass the population on untouched, with the item-linking chain PINNED. `Attach Identity` runs
// Once for Each Item and reads `$('Split Transactions').item`, and n8n does not auto-assign
// pairedItem for a node running Once for All Items - `Merge with previous_cases` sets it by hand
// for exactly this reason and records the live failure that taught it. Inserting this gate into
// that chain without pinning would sever it. Output item i came from input item i.
const _out = $input.all();
for (let i = 0; i < _out.length; i++) _out[i].pairedItem = { item: i };
return _out;

// Fail Loudly (MV Overstay Fines) - the end of the error rail.
//
// WHY THE RAIL EXISTS. This flow acquires the ERP lease before `Get Change of Status
// Transactions` and releases it at `Run Complete`, after both the run row and the verdict rows
// have been written. Until 2026-08-23 there was no lease at all; now that there is one, every
// way this flow can die between those two points - a breaker trip, a budget refusal, a dead
// token, a cohort assertion, a data-table write - would otherwise leave the lease held by a run
// that no longer exists, and the staleness backstop only clears it after 3 hours. That is a
// 3-hour hole in the queue after every failure, on a flow whose ERP phase runs long.
//
// WHY IT IS AN ERROR OUTPUT AND NOT THE ERROR TRIGGER. `On Workflow Crash` fires in a SEPARATE
// execution, where `$('Validate Inputs')` does not resolve - so it cannot name the run that
// holds the lease, and a release that guesses is the silent-steal path the lease exists to
// prevent. An error OUTPUT stays inside the same execution, so `Release Lease (error)` names the
// real holder. The Error Trigger keeps its own job of drafting the failure email; it does not
// touch the lease.
//
// WHY IT RE-THROWS. n8n marks an execution SUCCESS when it runs off the end of an error output -
// a routed error is a handled error as far as the engine is concerned. The rail this flow was
// built with did exactly that: every error output went to `Build Error Callback`, the portal was
// told the run had died, and the execution list showed a green tick. That is strictly worse than
// a stranded lease, because a stranded lease is loud within three hours and a run that claims to
// have finished is never looked at again.
//
// WHERE IT SITS AND WHY. It hangs off `Build Error Callback`, not off `Release Lease (error)`
// directly, so the portal callback is built and `Error Gate` is reached BEFORE this throws.
// `Error Gate` is drawn above this node on the canvas, and under executionOrder v1 that is what
// decides which sibling branch runs first - which is a real dependency on node position and is
// recorded here rather than left for someone to discover by moving a box.
const item = $input.first().json || {};

// The error output's shape is not guaranteed: n8n puts a string here for some node types and an
// object for others, and `Build Error Callback` has already normalised what it could. Read the
// normalised fields first, then fall back to the raw ones.
const raw = item.error;
const msg = (raw && typeof raw === 'object' && raw.message) ? String(raw.message)
          : (typeof raw === 'string' ? raw : String(item.message || 'unknown error'));
const failedNode = String((raw && raw.node && raw.node.name) || item.node || 'unknown node');

let runId = String(item.run_id || 'unknown');
let auditWindow = '';
try {
  const v = $('Validate Inputs').first().json;
  if (v && v.run_id) runId = String(v.run_id);
  auditWindow = String(v.range_start || '') + ' to ' + String(v.range_end || '');
} catch (e) { }

console.log(JSON.stringify({ stage: 'mv_overstay_fines_failed', run_id: runId,
  audit_window: auditWindow, failed_node: failedNode, error: msg,
  portal_told: item.result === 'error',
  note: 'ERP lease RELEASED on the error rail. Without it this run would have held the lease ' +
        'until the 3-hour staleness backstop, because Release ERP Lease sits at Run Complete ' +
        'and never runs when the flow dies.' }));

throw new Error('MV OVERSTAY FINES FAILED at "' + failedNode + '": ' + msg +
  ' | The ERP lease was released, so the next audit is not blocked. | The portal callback was ' +
  'built on this same rail, so the Security Room has been told the run ended. | Cases and ' +
  'verdicts for this run are incomplete or absent - do not read a partial data-table write as a ' +
  'finished audit. Re-run the same window once the cause is fixed.');

// ===================== ERP CIRCUIT BREAKER (ERP-LOAD-POLICY.md §5) =====================
// GENERATED - do not edit here. Canonical: audit-flows/tools/erp_breaker.js
// Re-generate with: python3 audit-flows/tools/build_breaker_embed.py --call-site plan --source-node "Validate Inputs"
//
// Pacing (§1) bounds requests per second. The pre-flight gate (§3) bounds how many there
// are. Neither notices that ERP has ALREADY STARTED FAILING and keeps feeding it the
// remaining ten thousand calls. This does. Aborting loses a run; not aborting loses ERP.
const ERP_BREAKER_DEFAULTS = {
  maxConsecutive: 5,        // §5: consecutive 5xx/429 -> abort
  latencyMultiple: 3,       // §5: mean per call above 3x the run's first batch -> abort
  degradedRateFloor: 0.25,  // added: a quarter of a batch failing is not a blip
  rateMinSamples: 20,       // ...but not judged on a handful of responses
  authWall: true,           // added: a batch that was refused outright and never once succeeded
  authWallMinSamples: 5     // ...over enough calls that it is a wall and not a coincidence
};

// The one header that would separate ERP's three refusals, read as a HEADER LOOKUP and never as
// a text scan. Two reasons, both load-bearing:
//
// 1. It is usually absent. On the node shape that produced the 2,400 pointless calls
//    (fullResponse + neverError:false) a refusal arrives as an n8n error object with no headers
//    at all, so this returns '' and the breaker falls back to the wall test. Where a node is
//    configured fullResponse + neverError:true the item IS {body, headers, statusCode,
//    statusMessage} - verified on execution 93601, workflow YXRZdtk2Geeeqaal - and then this
//    can speak. It enriches the MESSAGE; it is never what decides the trip.
//
// 2. IT MUST NOT BE MATCHED IN TEXT. That same verified 200 response carries
//    `access-control-expose-headers: ... developerMessage`, on EVERY successful call. A
//    has('developermessage') scan over the item would therefore match every healthy response
//    ERP returns - the identical bug shape as the bare `503` scan that classified a contract
//    id of 503 as a server error.
function erpBreakerDeveloperMessage(item) {
  const o = item && typeof item === 'object' ? item : {};
  const h = o.headers;
  if (!h || typeof h !== 'object' || Array.isArray(h)) return '';
  for (const k of Object.keys(h)) {
    if (String(k).toLowerCase() === 'developermessage') {
      const v = h[k];
      if (v === null || v === undefined) return '';
      return String(Array.isArray(v) ? v.join(',') : v).trim();
    }
  }
  return '';
}

// Classify one response item. Works on THREE different shapes, because which one arrives
// depends on how the HTTP node was configured and on how it failed:
//   - a normal parsed body (responseFormat: json)          -> ok, unless it is an error body
//   - an ERP error body (Spring shape: status/error/path)  -> classified by `status`
//   - an n8n error object (onError: continueRegularOutput) -> classified by scanning its text,
//     because n8n does not put the HTTP code anywhere predictable in it
// Scanning text is crude. It is also the only thing that works across all three, and a
// classifier that only understood the tidy shape would report a healthy run while ERP burned.
function erpBreakerClassify(item) {
  const o = item && typeof item === 'object' ? item : {};

  // An explicit numeric status wins over any text scan.
  let code = null;
  const candidates = [o.statusCode, o.status, o.httpCode, o.code,
                      o.error && o.error.httpCode, o.error && o.error.status];
  for (const c of candidates) {
    const n = Number(c);
    if (Number.isFinite(n) && n >= 100 && n < 600) { code = n; break; }
  }

  let text = '';
  try { text = JSON.stringify(o) || ''; } catch (e) { text = String(o); }
  text = text.slice(0, 4000).toLowerCase();

  function has(s) { return text.indexOf(s) !== -1; }

  // A BARE THREE-DIGIT SCAN MUST NOT BE POINTED AT A SUCCESSFUL BODY, and for a long time it
  // was. `has('503')` matched anywhere in the item's JSON, so a healthy response classified as
  // a server error the moment its DATA happened to contain those digits - a contract id of 503,
  // an id of 1502, or an amount of 5040, which is not hypothetical: 5040 is a real price on the
  // CC price card. Stage 2 ships per-contract payloads full of ids and amounts, so five
  // consecutive ordinary contracts could trip the breaker against a perfectly healthy ERP.
  //
  // That is the crying-wolf failure this file warns about elsewhere, and the reaction to a
  // spurious trip is to raise the thresholds until it stops - at which point it detects nothing.
  //
  // So the bare digits are scanned ONLY over the error region: what n8n puts under `error`, and
  // a top-level string `message`. The distinctive PHRASES stay on the full text, because they do
  // not appear in id data and they are what catches a Spring error body nested under `body` -
  // the one shape where the status code is not reachable as a number.
  let errText = '';
  const errBits = [];
  if (o.error !== undefined && o.error !== null) errBits.push(o.error);
  if (typeof o.message === 'string') errBits.push(o.message);
  try { errText = JSON.stringify(errBits) || ''; } catch (e) { errText = String(errBits); }
  errText = errText.slice(0, 4000).toLowerCase();

  function hasErr(s) { return errText.indexOf(s) !== -1; }

  // AUTH FIRST, and deliberately so. A 401 arriving in an n8n error object often also carries
  // the word "error" and a 500-ish wrapper; classified in the other order, the permanent 401
  // on every replacement call would read as a server error and trip the breaker on every run.
  const authish = (code === 401 || code === 403 || code === 498) ||
    has('insufficient_permissions') || has('unauthorized') || has('logout') ||
    has('unauthenticated') || has('securityexception') || has('token has expired') ||
    has('jwt expired') || has('forbidden');
  if (authish) return 'auth';

  if (code === 429 || has('too many requests') || has('rate limit') || has('rate-limit')) {
    return 'throttled';
  }
  if ((code !== null && code >= 500 && code < 600) ||
      has('internal server error') || has('bad gateway') || has('service unavailable') ||
      has('gateway time-out') || has('gateway timeout') ||
      hasErr('502') || hasErr('503') || hasErr('504')) {
    return 'server_error';
  }
